export const meta = {
  name: 'go3-review-pr114',
  description: 'Adversarial multi-lens review of my-pi PR #114 (footer panes + pi-agent-ui) → merge-readiness verdict',
  phases: [
    { title: 'Review', detail: '3 adversarial lenses review the #114 diff in parallel' },
    { title: 'Synthesize', detail: 'merge-readiness verdict from the lens findings' },
  ],
}

const PR = 114
const REPO_CWD = '/Users/luke/Projects/personal/my-pi'

const CONTEXT = `
Target: my-pi PR #${PR} "feat(tui): add runtime footer panes".
Repo cwd for gh: ${REPO_CWD} (run \`cd ${REPO_CWD} && gh pr diff ${PR}\` and \`gh pr view ${PR} --json body,files\`).
What it does: adds selectable footer/main-pane surfaces (monitors, workflows, durable planning tasks, TodoWrite) + a new \`packages/pi-agent-ui\` extension with wiring tests; updates fork-patch-inventory + completion-audit docs. ~20 files: extensions/{monitor,task-tools,pi-session-todo}, packages/pi-agent-ui/src/{extension.ts,extension.test.ts}, docs/*.
Dependency: there is a COMPANION CORE PR in valkyriweb/pi-mono for "interactive footer activation" — this my-pi PR may depend on core changes not yet merged.
This is Luke's PERSONAL Pi fork stack. Cache stability is sacred (see below). Be adversarial: default to skepticism, cite file:line evidence from the actual diff, do not invent issues.
`

const PI_CACHE = `
Pi prompt-cache footguns (HARD constraints — a violation here is a blocking finding):
- \`params.system\` and \`tools[]\` bytes must stay byte-stable across same-cwd sessions. Anything that makes a tool's schema/description or the system prompt vary per-turn or per-session busts the Anthropic prompt cache (position-0 bust if it lands in the system prefix).
- Dynamic/situational tools should be \`deferLoading: true\`; \`setActiveTools\` must only fire when the normalized tool-name set actually changes.
- Per-turn-billed surfaces (tool descriptions) should not grow needlessly.
`

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['lens', 'verdict', 'findings', 'summary'],
  properties: {
    lens: { type: 'string' },
    verdict: { type: 'string', enum: ['merge_ready', 'changes_needed', 'block'] },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['severity', 'file', 'issue', 'evidence'],
        properties: {
          severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] },
          file: { type: 'string' },
          issue: { type: 'string' },
          evidence: { type: 'string', description: 'concrete file:line or diff snippet proving it' },
        },
      },
    },
    summary: { type: 'string' },
  },
}

const LENSES = [
  {
    key: 'correctness',
    prompt: `${CONTEXT}\nLENS = CORRECTNESS. Read the actual diff. Judge: does the extension wiring + pi-agent-ui code actually work? Logic bugs, unhandled states, missing wiring, broken tests, inadequate test coverage for the new footer-pane surfaces. Verify the listed verification commands actually exercise the new code. Return structured findings with file:line evidence from the diff.`,
  },
  {
    key: 'cache-prompt-stability',
    prompt: `${CONTEXT}\n${PI_CACHE}\nLENS = CACHE / PROMPT-STABILITY. This is the highest-stakes lens for Luke's Pi fork. Read the diff and hunt for ANY change that could bust the prompt cache: new/changed tool schemas or descriptions, system-prompt mutations, per-turn-varying content in the cached prefix, setActiveTools without a name-set guard, tools registered without deferLoading that should be deferred. A real cache regression = blocker. Return findings with file:line evidence.`,
  },
  {
    key: 'scope-regression',
    prompt: `${CONTEXT}\nLENS = SCOPE / REGRESSION / DEPENDENCY. Judge: surface-area creep, fork-divergence risk, whether merging THIS my-pi PR without its companion core PR (valkyriweb/pi-mono interactive footer activation) would break or half-wire anything (e.g. UI that references a core capability not yet present). Does it risk the extension gate (test:extension-gate)? Any docs/inventory claims that don't match the code? Return findings with file:line evidence.`,
  },
]

phase('Review')
const reviews = await parallel(
  LENSES.map((l) => () =>
    agent(l.prompt, { label: `review:${l.key}`, phase: 'Review', schema: FINDINGS_SCHEMA })
  )
)
const valid = reviews.filter(Boolean)

phase('Synthesize')
const SYNTH_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['overall', 'blocking', 'recommended_action', 'summary'],
  properties: {
    overall: { type: 'string', enum: ['merge_ready', 'merge_with_nits', 'changes_needed', 'block', 'needs_core_pr_first'] },
    blocking: { type: 'array', items: { type: 'string' } },
    recommended_action: { type: 'string', description: 'concrete next step: merge / hold for core PR / request changes (which)' },
    summary: { type: 'string' },
  },
}
const verdict = await agent(
  `Synthesize a merge-readiness verdict for my-pi PR #${PR} from these 3 adversarial lens reviews. Do NOT re-review; weigh what the lenses found. A blocker in ANY lens (esp. cache/prompt-stability) gates merge. Account for the companion-core-PR dependency. Lens reviews (JSON):\n\n${JSON.stringify(valid, null, 2)}`,
  { label: 'synthesize-verdict', phase: 'Synthesize', schema: SYNTH_SCHEMA }
)

return { pr: PR, lenses: valid, verdict }

