async function refreshProjectMemorySnapshotBeforeInjection(db: MemoryDb, ctx: ExtensionContext): Promise<void> {
	const maxJobs = Math.max(1, Number.parseInt(process.env.PI_MEMORY_STARTUP_DREAM_MAX_JOBS ?? "5", 10) || 5);
	let ran = 0;
	while (ran < maxJobs && db.nextPendingExtractionJob(slug)) {
		const result = await runNextDreamConsolidationWithAgent(db, ctx, config, slug);
		ran++;
		if (result.status !== "completed") break;
	}
	if (isParentMemoryPromptSnapshotStale(slug)) {
		renderParentMemoryPromptSnapshot(slug, { maxBytes: config.indexMaxBytes, maxLines: config.indexMaxLines });
	}
}

function recordObservation(kind: ObservationKind, content: string, metadata?: Record<string, unknown>): void {
	if (!memoryDb || !originSessionId) return;
