366		pi.registerShortcut("alt+z", { description: "Zoom into the most recent running background agent", handler: enterZoomFromHotkey });
367		pi.registerShortcut("alt+l", { description: "Cycle to the next running background agent while zoomed", handler: (ctx) => cycleZoom(ctx, "next") });
368		pi.registerShortcut("alt+h", { description: "Cycle to the previous running background agent while zoomed", handler: (ctx) => cycleZoom(ctx, "prev") });
369		pi.registerShortcut("alt+i", { description: "Cooperatively interrupt the zoomed agent", handler: (ctx) => runZoomedTaskVerb(ctx, "requestShutdown") });
370		pi.registerShortcut("alt+k", { description: "Hard-stop the zoomed agent", handler: (ctx) => runZoomedTaskVerb(ctx, "kill") });
