import type {
	AgentRecentRun,
	ExtensionAPI,
	ExtensionContext,
	ExtensionMainPaneAPI,
	Theme,
} from "@valkyriweb/pi-coding-agent";
import type { Component, TUI } from "@valkyriweb/pi-tui";
import type { ZoomedSessionConfig } from "./components/zoomed-session-transcript.ts";

const STOPPED_DISPLAY_MS = 3000;

type ZoomPayload = { taskId: string; sessionConfig: ZoomedSessionConfig };
type BashZoomPayload = { bgId: string };
type PaneComponent = Component & { dispose?(): void; onEscape?(): boolean | undefined };
type PiRuntime = typeof import("@valkyriweb/pi-coding-agent");
type RunningAgentRun = Pick<AgentRecentRun, "id" | "startedAt" | "status">;
let zoomedTaskId: string | undefined;
let zoomedBashBgId: string | undefined;
let zoomAutoPopTimer: ReturnType<typeof setTimeout> | undefined;
let unsubscribeZoomStatus: (() => void) | undefined;
let extensionApi: ExtensionAPI | undefined;
let piRuntime: PiRuntime | undefined;
let piRuntimePromise: Promise<PiRuntime> | undefined;
let footerRefreshPromise: Promise<void> | undefined;
let runningTaskSnapshot: RunningAgentRun[] = [];

async function loadPiRuntime(): Promise<PiRuntime> {
	if (!piRuntimePromise) {
		piRuntimePromise = import("@valkyriweb/pi-coding-agent").then((runtime) => {
			piRuntime = runtime;
			refreshFooterSnapshotNow(runtime);
			return runtime;
		});
	}
	return piRuntimePromise;
}

function refreshFooterSnapshotNow(runtime: PiRuntime): void {
	runningTaskSnapshot = getRunningTasksSortedFrom(runtime.listAgentRecentRuns());
}

function scheduleFooterSnapshotRefresh(): void {
	if (piRuntime) {
		refreshFooterSnapshotNow(piRuntime);
		return;
	}
	if (footerRefreshPromise) return;
	footerRefreshPromise = loadPiRuntime()
		.then((runtime) => {
			refreshFooterSnapshotNow(runtime);
		})
		.catch(() => {})
		.finally(() => {
			footerRefreshPromise = undefined;
		});
}

function getRunningTasksSortedFrom(runs: readonly AgentRecentRun[]): RunningAgentRun[] {
	return runs
		.filter((run) => run.execution === "background" && run.status === "running")
		.sort((a, b) => Date.parse(a.startedAt) - Date.parse(b.startedAt));
}

function getRunningTasksSorted(): RunningAgentRun[] {
	if (!piRuntime) {
		scheduleFooterSnapshotRefresh();
		return runningTaskSnapshot;
	}
	refreshFooterSnapshotNow(piRuntime);
	return runningTaskSnapshot;
}

function cycleRunningTask(
	currentTaskId: string | undefined,
	direction: "next" | "prev",
	tasks: RunningAgentRun[] = getRunningTasksSorted(),
): RunningAgentRun | undefined {
	if (tasks.length === 0) return undefined;
	const currentIndex = currentTaskId ? tasks.findIndex((task) => task.id === currentTaskId) : -1;
	if (currentIndex === -1) return direction === "next" ? tasks[0] : tasks[tasks.length - 1];
	const offset = direction === "next" ? 1 : -1;
	const nextIndex = (currentIndex + offset + tasks.length) % tasks.length;
	return tasks[nextIndex];
}

class LazyErrorPane implements Component {
	private readonly label: string;
	private readonly error: unknown;

	constructor(label: string, error: unknown) {
		this.label = label;
		this.error = error;
	}

	render(): string[] {
		const message = this.error instanceof Error ? this.error.message : String(this.error);
		return [`Failed to load ${this.label}: ${message}`];
	}

	invalidate(): void {}
}

class LazyMainPane implements Component {
	private readonly ui: TUI;
	private readonly label: string;
	private readonly load: () => Promise<PaneComponent>;
	private loaded: PaneComponent | undefined;
	private loading: Promise<void> | undefined;
	private disposed = false;

	constructor(ui: TUI, label: string, load: () => Promise<PaneComponent>) {
		this.ui = ui;
		this.label = label;
		this.load = load;
	}

	get wantsKeyRelease(): boolean | undefined {
		return this.loaded?.wantsKeyRelease;
	}

	render(width: number): string[] {
		if (this.loaded) return this.loaded.render(width);
		this.ensureLoaded();
		return [`Loading ${this.label}...`];
	}

	handleInput(data: string): void {
		this.loaded?.handleInput?.(data);
	}

	onEscape(): boolean | undefined {
		return this.loaded?.onEscape?.();
	}

	dispose(): void {
		this.disposed = true;
		this.loaded?.dispose?.();
	}

	invalidate(): void {
		this.loaded?.invalidate();
	}

	private ensureLoaded(): void {
		if (this.loaded || this.loading) return;
		this.loading = this.load()
			.then((component) => {
				if (this.disposed) {
					component.dispose?.();
					return;
				}
				this.loaded = component;
				this.ui.requestRender();
			})
			.catch((error: unknown) => {
				if (this.disposed) return;
				this.loaded = new LazyErrorPane(this.label, error);
				this.ui.requestRender();
			});
	}
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null;
}

function zoomPayload(payload: unknown): ZoomPayload | undefined {
	if (!isRecord(payload) || typeof payload.taskId !== "string" || !isRecord(payload.sessionConfig)) return undefined;
	return { taskId: payload.taskId, sessionConfig: payload.sessionConfig as unknown as ZoomedSessionConfig };
}

function bashZoomPayload(payload: unknown): BashZoomPayload | undefined {
	if (!isRecord(payload) || typeof payload.bgId !== "string") return undefined;
	return { bgId: payload.bgId };
}

function makeZoomedSessionConfig(ctx: ExtensionContext): ZoomedSessionConfig {
	return { cwd: ctx.cwd };
}

function createZoomedTaskPane(ui: TUI, _theme: Theme, api: ExtensionMainPaneAPI): PaneComponent {
	const payload = zoomPayload(api.payload);
	return new LazyMainPane(ui, "zoom view", async () => {
		const { ZoomedTaskComponent } = await import("./components/zoomed-task.ts");
		if (!payload) return new ZoomedTaskComponent("unknown", ui, { cwd: process.cwd() });
		return new ZoomedTaskComponent(payload.taskId, ui, payload.sessionConfig, () => {
			void interruptZoomedTask(payload.taskId);
		});
	});
}

function createZoomedBashPane(ui: TUI, _theme: Theme, api: ExtensionMainPaneAPI): PaneComponent {
	const payload = bashZoomPayload(api.payload);
	return new LazyMainPane(ui, "shell zoom view", async () => {
		const { ZoomedBashComponent } = await import("./components/zoomed-bash.ts");
		return new ZoomedBashComponent(payload?.bgId ?? "unknown", ui);
	});
}

function disposeZoomedComponent(): void {
	if (zoomAutoPopTimer) {
		clearTimeout(zoomAutoPopTimer);
		zoomAutoPopTimer = undefined;
	}
	unsubscribeZoomStatus?.();
	unsubscribeZoomStatus = undefined;
	if (extensionApi) {
		extensionApi.hideMainPane("zoom");
		extensionApi.hideMainPane("bash-zoom");
	}
	zoomedTaskId = undefined;
	zoomedBashBgId = undefined;
}

function enterZoom(ctx: ExtensionContext, taskId: string): void {
	zoomedTaskId = taskId;
	zoomedBashBgId = undefined;
	extensionApi?.hideMainPane("bash-zoom");
	extensionApi?.showMainPane("zoom", { taskId, sessionConfig: makeZoomedSessionConfig(ctx) });
	void (async () => {
		const runtime = await loadPiRuntime();
		unsubscribeZoomStatus?.();
		unsubscribeZoomStatus = runtime.subscribeAgentRecentRuns(() => scheduleZoomTerminalCheck());
		scheduleZoomTerminalCheck();
	})();
}

function enterBashZoom(bgId: string): void {
	void enterBashZoomAsync(bgId);
}

async function enterBashZoomAsync(bgId: string): Promise<void> {
	const runtime = await loadPiRuntime();
	if (!runtime.getBashBgJob(bgId)) return;
	zoomedTaskId = undefined;
	zoomedBashBgId = bgId;
	unsubscribeZoomStatus?.();
	unsubscribeZoomStatus = undefined;
	if (zoomAutoPopTimer) {
		clearTimeout(zoomAutoPopTimer);
		zoomAutoPopTimer = undefined;
	}
	extensionApi?.hideMainPane("zoom");
	extensionApi?.showMainPane("bash-zoom", { bgId });
}

function enterZoomFromHotkey(ctx: ExtensionContext): void {
	void enterZoomFromHotkeyAsync(ctx);
}

async function enterZoomFromHotkeyAsync(ctx: ExtensionContext): Promise<void> {
	if (zoomedTaskId || zoomedBashBgId) {
		disposeZoomedComponent();
		return;
	}
	const runtime = await loadPiRuntime();
	const tasks = getRunningTasksSortedFrom(runtime.listAgentRecentRuns());
	runningTaskSnapshot = tasks;
	const target = tasks[tasks.length - 1];
	if (!target) {
		ctx.ui.notify("No running background agent to zoom into.", "warning");
		return;
	}
	enterZoom(ctx, target.id);
}

function cycleZoom(ctx: ExtensionContext, direction: "next" | "prev"): void {
	void cycleZoomAsync(ctx, direction);
}

async function cycleZoomAsync(ctx: ExtensionContext, direction: "next" | "prev"): Promise<void> {
	if (!zoomedTaskId) {
		await enterZoomFromHotkeyAsync(ctx);
		return;
	}
	const runtime = await loadPiRuntime();
	const tasks = getRunningTasksSortedFrom(runtime.listAgentRecentRuns());
	runningTaskSnapshot = tasks;
	const next = cycleRunningTask(zoomedTaskId, direction, tasks);
	if (!next) {
		disposeZoomedComponent();
		return;
	}
	enterZoom(ctx, next.id);
}

function injectIntoZoomedTask(ctx: ExtensionContext, text: string): void {
	const taskId = zoomedTaskId;
	if (!taskId) return;
	void (async () => {
		const runtime = await loadPiRuntime();
		runtime.appendTaskMessage(taskId, { kind: "user_injected", ts: Date.now(), text });
		try {
			const result = await runtime.LocalAgentTask.injectMessage?.(taskId, text);
			if (!result) {
				runtime.appendTaskMessage(taskId, { kind: "tool_end", ts: Date.now(), toolName: "inject", isError: true, resultPreview: "not supported" });
				ctx.ui.notify("Inject failed: not supported in this runtime", "warning");
				return;
			}
			runtime.appendTaskMessage(taskId, {
				kind: "tool_end",
				ts: Date.now(),
				toolName: "inject",
				isError: !result.ok,
				resultPreview: result.message,
			});
			if (!result.ok) ctx.ui.notify(`Inject failed: ${result.message}`, "warning");
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			runtime.appendTaskMessage(taskId, { kind: "tool_end", ts: Date.now(), toolName: "inject", isError: true, resultPreview: message });
			ctx.ui.notify(`Inject failed: ${message}`, "warning");
		}
	})();
}

async function interruptZoomedTask(taskId: string): Promise<void> {
	const runtime = await loadPiRuntime();
	const result = await runtime.interruptAgentRecentRun(taskId);
	if (!result.ok) extensionApi?.notify(`interrupt failed: ${result.message}`, "warning");
}

async function runZoomedTaskVerb(ctx: ExtensionContext, verb: "requestShutdown" | "kill"): Promise<void> {
	const taskId = zoomedTaskId;
	if (!taskId) return;
	const runtime = await loadPiRuntime();
	if (verb === "requestShutdown") {
		const result = await runtime.interruptAgentRecentRun(taskId);
		if (!result.ok) ctx.ui.notify(`${verb} failed: ${result.message}`, "warning");
		return;
	}
	const result = await runtime.cancelAgentRecentRun(taskId);
	if (!result.ok) ctx.ui.notify(`${verb} failed: ${result.message}`, "warning");
}

function scheduleZoomTerminalCheck(): void {
	void scheduleZoomTerminalCheckAsync();
}

async function scheduleZoomTerminalCheckAsync(): Promise<void> {
	const taskId = zoomedTaskId;
	if (!taskId || zoomAutoPopTimer) return;
	const runtime = await loadPiRuntime();
	const snapshot = runtime.findAgentRecentRun(taskId);
	if (!snapshot || snapshot.status === "running") return;
	zoomAutoPopTimer = setTimeout(() => {
		void (async () => {
			zoomAutoPopTimer = undefined;
			if (zoomedTaskId !== taskId) return;
			const current = (await loadPiRuntime()).findAgentRecentRun(taskId);
			if (current?.status === "running") return;
			disposeZoomedComponent();
		})();
	}, STOPPED_DISPLAY_MS);
}

export { cycleRunningTask, disposeZoomedComponent, enterBashZoom, enterZoom, getRunningTasksSorted };

export default function piAgentUi(pi: ExtensionAPI): void {
	extensionApi = pi;
	pi.registerMainPane("zoom", createZoomedTaskPane);
	pi.registerMainPane("bash-zoom", createZoomedBashPane);
	// Core backgroundTasksUi owns the active-work footer and /tasks pane. This
	// package keeps the focused zoom panes + hotkeys only, avoiding duplicate
	// footer pills for the same agent/shell runtime tasks.
	pi.registerShortcut("alt+z", { description: "Zoom into the most recent running background agent", handler: enterZoomFromHotkey });
	pi.registerShortcut("alt+l", { description: "Cycle to the next running background agent while zoomed", handler: (ctx) => cycleZoom(ctx, "next") });
	pi.registerShortcut("alt+h", { description: "Cycle to the previous running background agent while zoomed", handler: (ctx) => cycleZoom(ctx, "prev") });
	pi.registerShortcut("alt+i", { description: "Cooperatively interrupt the zoomed agent", handler: (ctx) => runZoomedTaskVerb(ctx, "requestShutdown") });
	pi.registerShortcut("alt+k", { description: "Hard-stop the zoomed agent", handler: (ctx) => runZoomedTaskVerb(ctx, "kill") });

	pi.on("input", (event, ctx) => {
		if (event.source !== "interactive" || (!zoomedTaskId && !zoomedBashBgId)) return { action: "continue" };
		const text = event.text.trim();
		if (!text) return { action: "handled" };
		if (text === "/exit-zoom") {
			disposeZoomedComponent();
			return { action: "handled" };
		}
		if (zoomedTaskId) injectIntoZoomedTask(ctx, text);
		return { action: "handled" };
	});
}

