type ZoomInputState = { zoomedTaskId?: string; zoomedBashBgId?: string };
type ZoomInputDecision = { action: "continue" | "handled"; effect?: "exit" | "inject" | "bash-readonly" };

/**
 * Pure routing for an interactive input line while a zoom pane is open.
 * - No zoom (or non-interactive source) → passthrough to the normal composer.
 * - Task zoom → inject the line into that agent.
 * - Bash zoom is a read-only log tail of a background shell job — there is no
 *   message channel into it, so a non-command line is *reported* rather than
 *   silently consumed (the original bug: it returned "handled" with no effect,
 *   eating the keystroke).
 */
function decideZoomInput(event: { source?: string; text: string }, state: ZoomInputState): ZoomInputDecision {
	if (event.source !== "interactive" || (!state.zoomedTaskId && !state.zoomedBashBgId)) return { action: "continue" };
	const text = event.text.trim();
	if (!text) return { action: "handled" };
	if (text === "/exit-zoom") return { action: "handled", effect: "exit" };
	if (state.zoomedTaskId) return { action: "handled", effect: "inject" };
	return { action: "handled", effect: "bash-readonly" };
}

export { cycleRunningTask, decideZoomInput, disposeZoomedComponent, enterBashZoom, enterZoom, getRunningTasksSorted };

