import { beforeAll, describe, expect, it, vi } from "vitest";
import { initTheme, type ExtensionAPI, type ExtensionMainPaneFactory, type Theme } from "@valkyriweb/pi-coding-agent";
import type { TUI } from "@valkyriweb/pi-tui";
import register, { decideZoomInput } from "./extension.ts";

function makeApi(): { api: ExtensionAPI; panes: Map<string, ExtensionMainPaneFactory> } {
	const panes = new Map<string, ExtensionMainPaneFactory>();
	const api = {
		registerMainPane: vi.fn((id: string, factory: ExtensionMainPaneFactory) => {
			panes.set(id, factory);
		}),
		registerCommand: vi.fn(),
		registerFooter: vi.fn(),
		registerShortcut: vi.fn(),
		on: vi.fn(),
		hideMainPane: vi.fn(),
		showMainPane: vi.fn(),
		notify: vi.fn(),
	} as unknown as ExtensionAPI;
	return { api, panes };
}

function makeUi(): TUI {
	return { requestRender: vi.fn(), notify: vi.fn() } as unknown as TUI;
}

beforeAll(() => {
	initTheme("dark", false);
});

describe("pi-agent-ui runtime extension", () => {
	it("registers panes and controls without importing zoom renderers eagerly", () => {
		const { api, panes } = makeApi();

		register(api);

		expect(panes.has("zoom")).toBe(true);
		expect(panes.has("bash-zoom")).toBe(true);
		expect(api.registerFooter).not.toHaveBeenCalled();
		expect(api.registerShortcut).toHaveBeenCalledTimes(5);
		expect(api.registerCommand).not.toHaveBeenCalled();
		expect(api.on).toHaveBeenCalledWith("input", expect.any(Function));
	});

	it("loads the task zoom renderer on first pane render", async () => {
		const { api, panes } = makeApi();
		const ui = makeUi();
		register(api);

		const pane = panes.get("zoom")?.(ui, {} as Theme, {
			payload: { taskId: "missing-task", sessionConfig: { cwd: process.cwd() } },
			requestHide: vi.fn(),
		});

		expect(pane?.render(80)).toEqual(["Loading zoom view..."]);
		await vi.waitFor(() => expect(ui.requestRender).toHaveBeenCalled());
		expect(pane?.render(80).join("\n")).toContain("Zoom: missing-task");
		expect(() => pane?.dispose?.()).not.toThrow();
	});

	it("loads the shell zoom renderer on first pane render", async () => {
		const { api, panes } = makeApi();
		const ui = makeUi();
		register(api);

		const pane = panes.get("bash-zoom")?.(ui, {} as Theme, {
			payload: { bgId: "missing-bg" },
			requestHide: vi.fn(),
		});

		expect(pane?.render(80)).toEqual(["Loading shell zoom view..."]);
		await vi.waitFor(() => expect(ui.requestRender).toHaveBeenCalled());
		expect(pane?.render(80).join("\n")).toContain("Shell");
		expect(() => pane?.dispose?.()).not.toThrow();
	});
});

describe("decideZoomInput", () => {
	it("passes through to the composer when no zoom is active", () => {
		expect(decideZoomInput({ source: "interactive", text: "hi" }, {})).toEqual({ action: "continue" });
	});

	it("passes through non-interactive input sources", () => {
		expect(decideZoomInput({ source: "programmatic", text: "hi" }, { zoomedTaskId: "t1" })).toEqual({ action: "continue" });
	});

	it("injects non-command input into the zoomed task", () => {
		expect(decideZoomInput({ source: "interactive", text: "do the thing" }, { zoomedTaskId: "t1" })).toEqual({
			action: "handled",
			effect: "inject",
		});
	});

	it("exits zoom on /exit-zoom (including from bash zoom)", () => {
		expect(decideZoomInput({ source: "interactive", text: "/exit-zoom" }, { zoomedBashBgId: "b1" })).toEqual({
			action: "handled",
			effect: "exit",
		});
	});

	it("reports bash-zoom input as read-only instead of silently swallowing it (regression)", () => {
		// Before the fix this returned { action: "handled" } with no effect, so
		// the keystroke vanished with no feedback. It must now surface an effect.
		expect(decideZoomInput({ source: "interactive", text: "hello" }, { zoomedBashBgId: "b1" })).toEqual({
			action: "handled",
			effect: "bash-readonly",
		});
	});

	it("treats whitespace-only input as handled with no effect", () => {
		expect(decideZoomInput({ source: "interactive", text: "   " }, { zoomedTaskId: "t1" })).toEqual({ action: "handled" });
	});
});

describe("re-registration resets module state", () => {
	it("tears down the prior registration's panes when the factory runs again", () => {
		const first = makeApi();
		register(first.api);
		const second = makeApi();
		register(second.api);
		// The reset path runs disposeZoomedComponent() against the still-old API,
		// so the previous registration's panes are hidden rather than leaked.
		expect(first.api.hideMainPane).toHaveBeenCalledWith("zoom");
		expect(first.api.hideMainPane).toHaveBeenCalledWith("bash-zoom");
	});
});

