85						const task = store.delete(taskId);
86						recordIfPossible(pi, store);
87						updatePlanningTaskWidget(ctx);
88						return taskResult(`Deleted ${task.id}: ${task.subject}`, { task, snapshot: store.snapshot() });
89					}
