91					recordIfPossible(pi, store);
92					updatePlanningTaskWidget(ctx);
93					return taskResult(`Updated ${task.id}: ${task.subject}`, { task, snapshot: store.snapshot() });
94				}
95				case "TaskList":
96				case "task_list": {
97					const tasks = store.list(decodeTaskListOptions(params));
98					return taskResult(formatTaskList(tasks, store.snapshot().tasks), { tasks });
99				}
100			}
101		} catch (error) {
102			return taskError(error);
103		}
