284		render(width: number): string[] {
285			const tasks = openPlanningTasks();
286			const active = tasks.filter((task) => task.status === "in_progress").length;
287			const lines = [
288				this.theme.fg("accent", this.theme.bold("Planning tasks")),
289				this.theme.fg("dim", `${active} active · ${tasks.length} open`),
290				this.theme.fg("dim", "↑↓ select · enter detail · esc close"),
291				"",
292			];
293			if (tasks.length === 0) lines.push(this.theme.fg("muted", "No open planning tasks."));
294			for (const [index, task] of tasks.entries()) {
295				const selected = index === this.selected;
296				const prefix = selected ? this.theme.fg("accent", "› ") : "  ";
297				const line = formatTask(task, new Set(tasks.map((t) => t.id)));
298				lines.push(`${prefix}${selected ? this.theme.fg("accent", line) : line}`);
299			}
300			if (this.detail) lines.push("", ...this.detail.split("\n").slice(0, 16).map((line) => this.theme.fg("muted", line)));
301			return lines.map((line) => (line.length > width ? `${line.slice(0, Math.max(0, width - 1))}…` : line));
302		}
