305	function updatePlanningTaskWidget(ctx: ExtensionContext | undefined): void {
306		if (!ctx?.hasUI || !ctx.ui?.setWidget) return;
307		const tasks = openPlanningTasks();
308		if (tasks.length === 0) {
309			ctx.ui.setWidget(TASK_WIDGET_KEY, undefined, { placement: "aboveEditor" });
310			return;
311		}
312		const theme = ctx.ui.theme as any;
313		const fg = (key: string, text: string) => (theme?.fg ? theme.fg(key, text) : text);
314		const bold = (text: string) => (theme?.bold ? theme.bold(text) : text);
315		const active = tasks.filter((task) => task.status === "in_progress").length;
316		const lines = [fg("toolTitle", bold(`Planning tasks ${active} active / ${tasks.length} open`))];
317		for (const task of tasks) lines.push(`  ${renderPlanningTaskLine(task, fg, bold)}`);
318		ctx.ui.setWidget(TASK_WIDGET_KEY, lines, { placement: "aboveEditor" });
319	}
