import type { AgentToolResult, ExtensionAPI, ExtensionContext } from "@valkyriweb/pi-coding-agent";
import { Effect } from "effect";

import {
	TaskCreateParams,
	TaskGetParams,
	TaskListParams,
	TaskUpdateParams,
	decodeTaskGet,
	decodeTaskListOptions,
	decodeTaskUpdate,
	normalizeTaskDraft,
	type PlanningTask,
} from "./schema.ts";
import { TaskStore, taskSnapshotEvent } from "./store.ts";

type ExtensionMainPaneComponent = {
	render(width: number): string[];
	invalidate(): void;
	handleInput(data: string): void;
	onEscape?(): boolean | undefined;
};
type ExtensionMainPaneFactory = (tui: { requestRender(): void }, theme: ExtensionContext["ui"]["theme"], api: { payload: unknown; requestHide(): void }) => ExtensionMainPaneComponent;
type B5ExtensionApi = ExtensionAPI & {
	registerMainPane?: (id: string, factory: ExtensionMainPaneFactory) => void;
	registerFooter?: (id: string, spec: { order?: number; visible?: () => boolean; render(ctx: { theme: ExtensionContext["ui"]["theme"]; selected: boolean; width: number }): string; onActivate(api: { close(): void }): void }) => void;
	showMainPane?: (id: string, payload?: unknown) => void;
};

export type PlanningTaskToolName =
	| "TaskCreate"
	| "TaskGet"
	| "TaskUpdate"
	| "TaskList"
	| "task_create"
	| "task_get"
	| "task_update"
	| "task_list";

const promptGuidelines = [
	"Use TaskCreate/TaskUpdate/TaskList for durable multi-step plans that must survive across turns; use TodoWrite only for ephemeral in-session checklists.",
	"Lowercase task_create/task_update/task_list remain Pi compatibility aliases; prefer Claude-cased Task* names for parity.",
	"Put workflow run ids, background task ids, agent run ids, or human labels in task owner/metadata; do not reuse runtime ids as planning task ids.",
	"Mark a task in_progress before starting work and completed immediately after it is fully done; represent blocked/failed with metadata/detail when Pi's status model has no direct state.",
	"Check TaskList before creating tasks to avoid duplicates; claim a task by setting owner.",
];

const PLANNING_TASKS_PANE_ID = "planning-tasks";

let store = new TaskStore();

export function initPlanningTaskStoreFromEntries(entries: unknown[]): void {
	store = TaskStore.fromEntries(entries);
}

export function planningTaskStoreSnapshot() {
	return store.snapshot();
}

export async function executePlanningTaskTool(
	name: PlanningTaskToolName,
	params: unknown,
	pi?: Pick<ExtensionAPI, "appendEntry">,
	ctx?: ExtensionContext,
): Promise<AgentToolResult<unknown>> {
	try {
		switch (name) {
			case "TaskCreate":
			case "task_create": {
				const task = store.create(normalizeTaskDraft(params));
				recordIfPossible(pi, store);
				updatePlanningTaskWidget(ctx);
				return taskResult(`Created ${task.id}: ${task.subject}`, { task, snapshot: store.snapshot() });
			}
			case "TaskGet":
			case "task_get": {
				const { task_id: taskId } = decodeTaskGet(params);
				const task = store.get(taskId);
				return taskResult(task ? formatTask(task) : `Task not found: ${taskId}`, { task: task ?? null });
			}
			case "TaskUpdate":
			case "task_update": {
				const { task_id: taskId, status, ...update } = decodeTaskUpdate(params);
				if (status === "deleted") {
					const task = store.delete(taskId);
					recordIfPossible(pi, store);
					updatePlanningTaskWidget(ctx);
					return taskResult(`Deleted ${task.id}: ${task.subject}`, { task, snapshot: store.snapshot() });
				}
				const task = store.update(taskId, { ...update, status });
				recordIfPossible(pi, store);
				updatePlanningTaskWidget(ctx);
				return taskResult(`Updated ${task.id}: ${task.subject}`, { task, snapshot: store.snapshot() });
			}
			case "TaskList":
			case "task_list": {
				const tasks = store.list(decodeTaskListOptions(params));
				return taskResult(formatTaskList(tasks, store.snapshot().tasks), { tasks });
			}
		}
	} catch (error) {
		return taskError(error);
	}
}

export function registerPlanningTaskTools(pi: ExtensionAPI): void {
	pi.registerTool<typeof TaskCreateParams, any>({
		name: "TaskCreate",
		deferLoading: true,
		label: "TaskCreate",
		renderShell: "hidden" as any,
		description:
			"Create a durable persistent planning task. This is not TodoWrite: it persists in task-tools storage and may be linked to workflow/background runtime ids via owner or metadata. Pass flat top-level fields: {subject, description?, activeForm?, metadata?, blockedBy?, owner?}. A subject is required. Tasks are created pending.",
		promptSnippet: "create durable planning tasks for multi-step work",
		promptGuidelines,
		parameters: TaskCreateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("TaskCreate", params, pi, ctx),
	});

	pi.registerTool<typeof TaskGetParams, any>({
		name: "TaskGet",
		deferLoading: true,
		label: "TaskGet",
		renderShell: "hidden" as any,
		description: "Get one durable persistent planning task by planning task id. Does not read runtime/background task output.",
		promptSnippet: "inspect one durable planning task",
		promptGuidelines,
		parameters: TaskGetParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("TaskGet", params, pi, ctx),
	});

	pi.registerTool<typeof TaskUpdateParams, any>({
		name: "TaskUpdate",
		deferLoading: true,
		label: "TaskUpdate",
		renderShell: "hidden" as any,
		description:
			"Update a durable persistent planning task by task_id. Set status (pending|in_progress|completed; deleted permanently removes the task), subject/description/activeForm/owner, merge metadata (a key set to null deletes it), or edit dependencies. For workflow blocked/failed states, keep Pi status pending/in_progress as appropriate and store the blocked/failed detail in metadata or description. Only mark completed when fully done.",
		promptSnippet: "update durable planning task status, owner, metadata, or dependencies",
		promptGuidelines,
		parameters: TaskUpdateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("TaskUpdate", params, pi, ctx),
	});

	pi.registerTool<typeof TaskListParams, any>({
		name: "TaskList",
		deferLoading: true,
		label: "TaskList",
		renderShell: "hidden" as any,
		description:
			"List durable persistent planning tasks sorted by readiness and creation time. This lists planning tasks, not background runtime jobs; use TaskBackgroundList or /tasks to discover runtime task_ids and output paths; use TaskStop only for runtime cancellation.",
		promptSnippet: "list durable planning tasks sorted by dependency readiness",
		promptGuidelines,
		parameters: TaskListParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("TaskList", params, pi, ctx),
	});

	registerLowercaseAliases(pi);
}

function registerLowercaseAliases(pi: ExtensionAPI): void {
	pi.registerTool<typeof TaskCreateParams, any>({
		name: "task_create",
		deferLoading: true,
		label: "task_create",
		renderShell: "hidden" as any,
		description:
			"Compatibility alias for TaskCreate. Prefer TaskCreate for Claude Code parity. Creates a durable persistent planning task, not an ephemeral TodoWrite item.",
		promptSnippet: "create persistent planning tasks for multi-step work",
		promptGuidelines,
		parameters: TaskCreateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("task_create", params, pi, ctx),
	});

	pi.registerTool<typeof TaskGetParams, any>({
		name: "task_get",
		deferLoading: true,
		label: "task_get",
		renderShell: "hidden" as any,
		description: "Compatibility alias for TaskGet. Prefer TaskGet for Claude Code parity.",
		promptSnippet: "inspect one persistent planning task",
		promptGuidelines,
		parameters: TaskGetParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("task_get", params, pi, ctx),
	});

	pi.registerTool<typeof TaskUpdateParams, any>({
		name: "task_update",
		deferLoading: true,
		label: "task_update",
		renderShell: "hidden" as any,
		description: "Compatibility alias for TaskUpdate. Prefer TaskUpdate for Claude Code parity.",
		promptSnippet: "update persistent planning task status, owner, or dependencies",
		promptGuidelines,
		parameters: TaskUpdateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("task_update", params, pi, ctx),
	});

	pi.registerTool<typeof TaskListParams, any>({
		name: "task_list",
		deferLoading: true,
		label: "task_list",
		renderShell: "hidden" as any,
		description: "Compatibility alias for TaskList. Prefer TaskList for Claude Code parity. Lists durable planning tasks, not background runtime jobs.",
		promptSnippet: "list persistent planning tasks sorted by dependency readiness",
		promptGuidelines,
		parameters: TaskListParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool("task_list", params, pi, ctx),
	});
}

export default function taskToolsExtension(pi: ExtensionAPI): void {
	const b5 = pi as B5ExtensionApi;
	if (typeof b5.registerMainPane === "function" && typeof b5.registerFooter === "function" && typeof b5.showMainPane === "function") {
		b5.registerMainPane(PLANNING_TASKS_PANE_ID, (tui, theme, api) => new PlanningTasksPane(tui, theme, api.requestHide));
		b5.registerFooter(PLANNING_TASKS_PANE_ID, {
			order: -6,
			visible: () => openPlanningTasks().length > 0,
			render: ({ theme, selected }) => planningTasksFooterText(theme, selected),
			onActivate: () => b5.showMainPane?.(PLANNING_TASKS_PANE_ID),
		});
	}
	pi.on("session_start", (_event, ctx) => {
		initPlanningTaskStoreFromEntries(ctx.sessionManager.getBranch());
		updatePlanningTaskWidget(ctx);
	});
	registerPlanningTaskTools(pi);
}

const TASK_WIDGET_KEY = "planning-tasks";

function openPlanningTasks(): PlanningTask[] {
	return store.snapshot().tasks.filter((task) => task.status !== "completed");
}

function planningTasksFooterText(theme: ExtensionContext["ui"]["theme"], selected: boolean): string {
	const tasks = openPlanningTasks();
	if (tasks.length === 0) return "";
	const active = tasks.filter((task) => task.status === "in_progress").length;
	const marker = selected ? "▶ " : "● ";
	return theme.fg(selected ? "accent" : "dim", `${marker}${tasks.length} task${tasks.length === 1 ? "" : "s"}${active ? ` · ${active} active` : ""} · enter plan`);
}

class PlanningTasksPane implements ExtensionMainPaneComponent {
	private selected = 0;
	private detail: string | undefined;

	constructor(
		private readonly tui: { requestRender(): void },
		private readonly theme: ExtensionContext["ui"]["theme"],
		private readonly requestHide: () => void,
	) {}

	onEscape(): boolean {
		this.requestHide();
		return true;
	}

	invalidate(): void {}

	handleInput(data: string): void {
		const tasks = openPlanningTasks();
		if (data === "\u001b[A") {
			this.selected = Math.max(0, this.selected - 1);
			this.detail = undefined;
			this.tui.requestRender();
			return;
		}
		if (data === "\u001b[B") {
			this.selected = Math.min(Math.max(0, tasks.length - 1), this.selected + 1);
			this.detail = undefined;
			this.tui.requestRender();
			return;
		}
		if (data === "\r" || data === "\n") {
			const task = tasks[this.selected];
			this.detail = task ? formatTaskDetail(task) : "No planning task selected.";
			this.tui.requestRender();
			return;
		}
		if (data === "\u001b") this.requestHide();
	}

	render(width: number): string[] {
		const tasks = openPlanningTasks();
		const active = tasks.filter((task) => task.status === "in_progress").length;
		const lines = [
			this.theme.fg("accent", this.theme.bold("Planning tasks")),
			this.theme.fg("dim", `${active} active · ${tasks.length} open`),
			this.theme.fg("dim", "↑↓ select · enter detail · esc close"),
			"",
		];
		if (tasks.length === 0) lines.push(this.theme.fg("muted", "No open planning tasks."));
		for (const [index, task] of tasks.entries()) {
			const selected = index === this.selected;
			const prefix = selected ? this.theme.fg("accent", "› ") : "  ";
			const line = formatTask(task, new Set(tasks.map((t) => t.id)));
			lines.push(`${prefix}${selected ? this.theme.fg("accent", line) : line}`);
		}
		if (this.detail) lines.push("", ...this.detail.split("\n").slice(0, 16).map((line) => this.theme.fg("muted", line)));
		return lines.map((line) => (line.length > width ? `${line.slice(0, Math.max(0, width - 1))}…` : line));
	}
}

function updatePlanningTaskWidget(ctx: ExtensionContext | undefined): void {
	if (!ctx?.hasUI || !ctx.ui?.setWidget) return;
	const tasks = openPlanningTasks();
	if (tasks.length === 0) {
		ctx.ui.setWidget(TASK_WIDGET_KEY, undefined, { placement: "aboveEditor" });
		return;
	}
	const theme = ctx.ui.theme as any;
	const fg = (key: string, text: string) => (theme?.fg ? theme.fg(key, text) : text);
	const bold = (text: string) => (theme?.bold ? theme.bold(text) : text);
	const active = tasks.filter((task) => task.status === "in_progress").length;
	const lines = [fg("toolTitle", bold(`Planning tasks ${active} active / ${tasks.length} open`))];
	for (const task of tasks) lines.push(`  ${renderPlanningTaskLine(task, fg, bold)}`);
	ctx.ui.setWidget(TASK_WIDGET_KEY, lines, { placement: "aboveEditor" });
}

function renderPlanningTaskLine(
	task: PlanningTask,
	fg: (key: string, text: string) => string,
	bold: (text: string) => string,
): string {
	const label = task.status === "in_progress" && task.activeForm ? task.activeForm : task.subject;
	const icon = task.status === "in_progress" ? "◐" : "☐";
	const base = task.status === "in_progress" ? fg("accent", bold(`${icon} ${task.id} ${label}`)) : fg("muted", `${icon} ${task.id} ${label}`);
	const owner = task.owner ? ` owner=${task.owner}` : "";
	const blockedBy = task.blockedBy.length > 0 ? ` blocked_by=${task.blockedBy.join(",")}` : "";
	const metadata = task.metadata && Object.keys(task.metadata).length > 0 ? ` metadata=${JSON.stringify(task.metadata)}` : "";
	return `${base}${fg("dim", `${owner}${blockedBy}${metadata}`)}`;
}

function recordTaskSnapshot(pi: Pick<ExtensionAPI, "appendEntry">, store: TaskStore): Effect.Effect<void> {
	return Effect.sync(() => {
		pi.appendEntry("task-tools", taskSnapshotEvent(store));
	});
}

function recordIfPossible(pi: Pick<ExtensionAPI, "appendEntry"> | undefined, store: TaskStore): void {
	if (!pi) return;
	Effect.runSync(recordTaskSnapshot(pi, store));
}

function taskResult<TDetails>(text: string, details: TDetails): AgentToolResult<TDetails> {
	return { content: [{ type: "text", text }], details };
}

function taskError(error: unknown): AgentToolResult<{ error: string }> {
	return {
		content: [{ type: "text", text: error instanceof Error ? error.message : String(error) }],
		details: { error: error instanceof Error ? error.message : String(error) },
		isError: true,
	} as AgentToolResult<{ error: string }> & { isError: boolean };
}

function formatTaskList(tasks: PlanningTask[], all: PlanningTask[]): string {
	if (all.length === 0) return "No tasks.";
	const done = all.filter((task) => task.status === "completed").length;
	const inProgress = all.filter((task) => task.status === "in_progress").length;
	const open = all.length - done - inProgress;
	const header = `${all.length} tasks (${done} done, ${inProgress} in progress, ${open} open)`;
	const openIds = new Set(all.filter((task) => task.status !== "completed").map((task) => task.id));
	return [header, ...tasks.map((task) => formatTask(task, openIds))].join("\n");
}

function formatTask(task: PlanningTask, openIds?: Set<string>): string {
	const label = task.status === "in_progress" && task.activeForm ? task.activeForm : task.subject;
	const owner = task.owner ? ` owner=${task.owner}` : "";
	const blockers = openIds ? task.blockedBy.filter((id) => openIds.has(id)) : task.blockedBy;
	const blockedBy = blockers.length > 0 ? ` blocked_by=${blockers.join(",")}` : "";
	const blocks = task.blocks.length > 0 ? ` blocks=${task.blocks.join(",")}` : "";
	return `${task.id} [${task.status}] ${label}${owner}${blockedBy}${blocks}`;
}

function formatTaskDetail(task: PlanningTask): string {
	const lines = [
		`${task.id} [${task.status}] ${task.subject}`,
		`created: ${new Date(task.createdAt).toISOString()}`,
		`updated: ${new Date(task.updatedAt).toISOString()}`,
	];
	if (task.activeForm) lines.push(`active: ${task.activeForm}`);
	if (task.description) lines.push(`description: ${task.description}`);
	if (task.owner) lines.push(`owner: ${task.owner}`);
	if (task.blockedBy.length > 0) lines.push(`blocked by: ${task.blockedBy.join(", ")}`);
	if (task.blocks.length > 0) lines.push(`blocks: ${task.blocks.join(", ")}`);
	if (task.metadata && Object.keys(task.metadata).length > 0) lines.push(`metadata: ${JSON.stringify(task.metadata)}`);
	return lines.join("\n");
}

