import type { AgentToolResult, ContextEvent, ExtensionAPI, ExtensionContext } from "@valkyriweb/pi-coding-agent";
import { Effect } from "effect";

import {
	TaskCreateParams,
	TaskGetParams,
	TaskListParams,
	TaskUpdateParams,
	decodeTaskGet,
	decodeTaskListOptions,
	decodeTaskUpdate,
	normalizeTaskDraft,
	type PlanningTask,
} from "./schema.ts";
import { TaskStore, taskSnapshotEvent } from "./store.ts";

type ThemeLike = ExtensionContext["ui"]["theme"];
type ExtensionMainPaneComponent = {
	render(width: number): string[];
	invalidate(): void;
	handleInput(data: string): void;
	onEscape?(): boolean | undefined;
};
type ExtensionMainPaneFactory = (tui: { requestRender(): void }, theme: ThemeLike, api: { payload: unknown; requestHide(): void }) => ExtensionMainPaneComponent;
type B5ExtensionApi = ExtensionAPI & {
	registerMainPane?: (id: string, factory: ExtensionMainPaneFactory) => void;
	showMainPane?: (id: string, payload?: unknown) => void;
};

export type PlanningTaskToolName =
	| "TaskCreate"
	| "TaskGet"
	| "TaskUpdate"
	| "TaskList"
	| "task_create"
	| "task_get"
	| "task_update"
	| "task_list";

const TASK_WIDGET_KEY = "planning-tasks";
const TASK_PANE_ID = "planning-tasks";

const promptGuidelines = [
	"Use TaskCreate/TaskUpdate/TaskList as the live checklist for multi-step work; TodoWrite is legacy and should not be used in this profile.",
	"Before updating a task after interruption, pivot, or stale state, read its latest state with TaskGet.",
	"Mark a task in_progress before starting work and completed immediately after it is fully done; failing tests, blockers, or partial work stay in_progress.",
	"When direction changes, update task subject/description/activeForm for still-relevant work and delete obsolete tasks with status:'deleted'.",
	"Use blockedBy/addBlockedBy/addBlocks to model dependencies; TaskList shows open blockers, TaskGet shows full dependency detail.",
	"Put agent run ids, workflow ids, background ids, or human labels in owner/metadata; do not reuse runtime ids as planning task ids.",
	"Check TaskList before creating tasks to avoid duplicates; claim available work by setting owner.",
];

let store = new TaskStore();

// ── CC-style task reminder: append-only, cache-safe heartbeat ────────────────
// Claude Code keeps its task list "live" by re-injecting a <system-reminder>
// with the current list every ~10 idle turns (CC's TURNS_SINCE_WRITE /
// TURNS_BETWEEN_REMINDERS, both 10). Pi previously only painted a TUI widget plus
// a one-shot completion nudge, so once the original tool results scrolled out of
// context the list went dormant and the agent drifted onto other work. We port
// the heartbeat through the `context` hook, which is transient per-call (never
// written back to session history) and strictly APPEND-ONLY at the tail: the
// cached prefix (system prompt, tools, prior turns) stays byte-identical, so it
// never bursts the prompt cache. Disable with PI_TASK_REMINDER_DISABLED=1; tune
// the idle-turn threshold with PI_TASK_REMINDER_TURNS (default 10).
const REMINDER_DISABLED = process.env.PI_TASK_REMINDER_DISABLED === "1";
const REMINDER_TURNS = parsePositiveInt(process.env.PI_TASK_REMINDER_TURNS, 10);

// Assistant turns since the agent last touched any Task* tool, and since the
// reminder last fired. Both must reach REMINDER_TURNS before a reminder is
// re-injected, mirroring CC's two-counter throttle.
let turnsSinceTaskTool = 0;
let turnsSinceReminder = 0;

function parsePositiveInt(raw: string | undefined, fallback: number): number {
	const value = Number(raw);
	return Number.isInteger(value) && value > 0 ? value : fallback;
}

function resetReminderCounters(): void {
	turnsSinceTaskTool = 0;
	turnsSinceReminder = 0;
}

export function initPlanningTaskStoreFromEntries(entries: unknown[]): void {
	store = TaskStore.fromEntries(entries);
}

export function planningTaskStoreSnapshot() {
	return store.snapshot();
}

export async function executePlanningTaskTool(
	name: PlanningTaskToolName,
	params: unknown,
	pi?: Pick<ExtensionAPI, "appendEntry">,
	ctx?: ExtensionContext,
): Promise<AgentToolResult<unknown>> {
	try {
		// Any task-tool interaction counts as "the list is being used": reset the
		// idle counter so the reminder heartbeat only fires when the agent has
		// genuinely stopped touching the checklist.
		turnsSinceTaskTool = 0;
		switch (name) {
			case "TaskCreate":
			case "task_create": {
				const task = store.create(normalizeTaskDraft(params));
				recordIfPossible(pi, store);
				updatePlanningTaskWidget(ctx);
				return taskResult(`Task #${displayId(task.id)} created successfully: ${task.subject}`, { task, snapshot: store.snapshot() });
			}
			case "TaskGet":
			case "task_get": {
				const { task_id: taskId } = decodeTaskGet(params);
				const task = store.get(taskId);
				return taskResult(task ? formatTaskDetail(task) : "Task not found", { task: task ?? null });
			}
			case "TaskUpdate":
			case "task_update": {
				const { task_id: taskId, status, ...update } = decodeTaskUpdate(params);
				if (status === "deleted") {
					const task = store.delete(taskId);
					recordIfPossible(pi, store);
					updatePlanningTaskWidget(ctx);
					return taskResult(`Deleted task #${displayId(task.id)}: ${task.subject}`, { task, snapshot: store.snapshot() });
				}
				const before = store.get(taskId);
				const task = store.update(taskId, { ...update, status });
				recordIfPossible(pi, store);
				updatePlanningTaskWidget(ctx);
				let text = `Updated task #${displayId(task.id)}`;
				if (before && before.status !== task.status && task.status === "completed") {
					text += "\nTask completed. Call TaskList now to find your next available task or see if your work unblocked others.";
				}
				return taskResult(text, { task, snapshot: store.snapshot() });
			}
			case "TaskList":
			case "task_list": {
				const tasks = store.list(decodeTaskListOptions(params));
				return taskResult(formatTaskList(tasks), { tasks });
			}
		}
	} catch (error) {
		return taskError(error);
	}
}

export default function taskToolsExtension(pi: ExtensionAPI): void {
	registerPlanningTaskUi(pi);
	pi.on("session_start", (_event, ctx) => {
		initPlanningTaskStoreFromEntries(ctx.sessionManager.getBranch());
		resetReminderCounters();
		updatePlanningTaskWidget(ctx);
	});
	pi.on("turn_start", () => {
		turnsSinceTaskTool += 1;
		turnsSinceReminder += 1;
	});
	pi.on("context", (event) => maybeInjectTaskReminder(event));
	registerPlanningTaskTools(pi);
}

function registerPlanningTaskUi(pi: ExtensionAPI): void {
	const b5 = pi as B5ExtensionApi;
	if (typeof b5.registerMainPane !== "function") return;
	b5.registerMainPane(TASK_PANE_ID, (tui, theme, api) => new PlanningTasksPane(tui, theme, api.requestHide));
}

export function registerPlanningTaskTools(pi: ExtensionAPI): void {
	registerTaskCreate(pi, "TaskCreate", "Create a new task in the task list");
	registerTaskGet(pi, "TaskGet", "Get a task by ID from the task list");
	registerTaskUpdate(pi, "TaskUpdate", "Update a task in the task list");
	registerTaskList(pi, "TaskList", "List all tasks in the task list");
	registerTaskCreate(pi, "task_create", "Compatibility alias for TaskCreate. Prefer TaskCreate for Claude Code parity.");
	registerTaskGet(pi, "task_get", "Compatibility alias for TaskGet. Prefer TaskGet for Claude Code parity.");
	registerTaskUpdate(pi, "task_update", "Compatibility alias for TaskUpdate. Prefer TaskUpdate for Claude Code parity.");
	registerTaskList(pi, "task_list", "Compatibility alias for TaskList. Prefer TaskList for Claude Code parity.");
}

function registerTaskCreate(pi: ExtensionAPI, name: "TaskCreate" | "task_create", description: string): void {
	pi.registerTool<typeof TaskCreateParams, any>({
		name,
		deferLoading: true,
		label: name,
		renderShell: "hidden" as any,
		description:
			`${description}. Creates a persistent checklist task. Fields: subject, description, optional activeForm, metadata, blockedBy, owner. All tasks are created pending. Check TaskList first to avoid duplicates.`,
		promptSnippet: "create persistent checklist tasks for multi-step work",
		promptGuidelines,
		parameters: TaskCreateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool(name, params, pi, ctx),
	});
}

function registerTaskGet(pi: ExtensionAPI, name: "TaskGet" | "task_get", description: string): void {
	pi.registerTool<typeof TaskGetParams, any>({
		name,
		deferLoading: true,
		label: name,
		renderShell: "hidden" as any,
		description:
			`${description}. Use taskId (Claude Code) or task_id (Pi) to retrieve full task details including description, owner, status, blocks, and blockedBy. Read latest state before updating stale/interrupted work.`,
		promptSnippet: "inspect one persistent checklist task",
		promptGuidelines,
		parameters: TaskGetParams,
		execute: async (_toolCallId, params) => executePlanningTaskTool(name, params, pi),
	});
}

function registerTaskUpdate(pi: ExtensionAPI, name: "TaskUpdate" | "task_update", description: string): void {
	pi.registerTool<typeof TaskUpdateParams, any>({
		name,
		deferLoading: true,
		label: name,
		renderShell: "hidden" as any,
		description:
			`${description}. Use taskId (Claude Code) or task_id (Pi). Status workflow is pending -> in_progress -> completed; status deleted permanently removes the task and scrubs blocker links. Update subject/description/activeForm/owner/metadata; metadata null deletes a key. Use addBlockedBy/addBlocks for dependencies. Only mark completed when fully done; blocked or partial work stays in_progress.`,
		promptSnippet: "update persistent checklist task status, owner, metadata, or dependencies",
		promptGuidelines,
		parameters: TaskUpdateParams,
		execute: async (_toolCallId, params, _onUpdate, _signal, ctx) => executePlanningTaskTool(name, params, pi, ctx),
	});
}

function registerTaskList(pi: ExtensionAPI, name: "TaskList" | "task_list", description: string): void {
	pi.registerTool<typeof TaskListParams, any>({
		name,
		deferLoading: true,
		label: name,
		renderShell: "hidden" as any,
		description:
			`${description}. Lists persistent checklist tasks sorted by readiness and creation time. Shows open blockers only so newly unblocked work is clear. Use includeCompleted:true for completed history.`,
		promptSnippet: "list persistent checklist tasks sorted by readiness",
		promptGuidelines,
		parameters: TaskListParams,
		execute: async (_toolCallId, params) => executePlanningTaskTool(name, params, pi),
	});
}

class PlanningTasksPane implements ExtensionMainPaneComponent {
	private selected = 0;
	private detail: string | undefined;

	constructor(
		private readonly tui: { requestRender(): void },
		private readonly theme: ThemeLike,
		private readonly requestHide: () => void,
	) {}

	onEscape(): boolean {
		this.requestHide();
		return true;
	}

	invalidate(): void {}

	handleInput(data: string): void {
		const tasks = openTasks();
		if (data === "\u001b[A") {
			this.selected = Math.max(0, this.selected - 1);
			this.detail = undefined;
			this.tui.requestRender();
			return;
		}
		if (data === "\u001b[B") {
			this.selected = Math.min(Math.max(0, tasks.length - 1), this.selected + 1);
			this.detail = undefined;
			this.tui.requestRender();
			return;
		}
		if (data === "\r" || data === "\n") {
			const task = tasks[this.selected];
			this.detail = task ? formatTaskDetail(task) : "No task selected.";
			this.tui.requestRender();
			return;
		}
		if (data === "\u001b") this.requestHide();
	}

	render(width: number): string[] {
		const tasks = openTasks();
		this.selected = Math.min(this.selected, Math.max(0, tasks.length - 1));
		const done = store.snapshot().tasks.filter((task) => task.status === "completed").length;
		const active = tasks.filter((task) => task.status === "in_progress").length;
		const lines = [
			this.theme.fg("accent", this.theme.bold("Tasks")),
			this.theme.fg("dim", `${done} done · ${active} active · ${tasks.length} open`),
			this.theme.fg("dim", "↑↓ select · enter detail · esc close"),
			"",
		];
		if (tasks.length === 0) lines.push(this.theme.fg("muted", "No open tasks."));
		for (const [index, task] of tasks.entries()) {
			const selected = index === this.selected;
			const prefix = selected ? this.theme.fg("accent", "› ") : "  ";
			const line = renderTaskLine(task, (key, text) => this.theme.fg(key as Parameters<ThemeLike["fg"]>[0], text), (text) => this.theme.bold(text));
			lines.push(`${prefix}${line}`);
		}
		if (this.detail) lines.push("", ...this.detail.split("\n").slice(0, 16).map((line) => this.theme.fg("muted", line)));
		return lines.map((line) => (line.length > width ? `${line.slice(0, Math.max(0, width - 1))}…` : line));
	}
}

function openTasks(): PlanningTask[] {
	return store.list({ includeCompleted: false });
}

// Re-inject the open task list as a transient <system-reminder> once the agent
// has gone REMINDER_TURNS turns without touching the tools AND without a recent
// reminder. Returns undefined (no change) unless there are open tasks to nudge
// about. The reminder is appended to the END of the messages array only, so the
// cached prefix is preserved.
function maybeInjectTaskReminder(event: ContextEvent): { messages: ContextEvent["messages"] } | undefined {
	if (REMINDER_DISABLED) return undefined;
	if (turnsSinceTaskTool < REMINDER_TURNS || turnsSinceReminder < REMINDER_TURNS) return undefined;
	const tasks = openTasks();
	if (tasks.length === 0) return undefined;
	turnsSinceReminder = 0;
	const reminder: ContextEvent["messages"][number] = {
		role: "user",
		content: [{ type: "text", text: buildReminderText(tasks) }],
		timestamp: Date.now(),
	};
	// Append-only at the tail keeps the cached prefix byte-identical (no burst).
	const messages: ContextEvent["messages"] = [...event.messages, reminder];
	return { messages };
}

function buildReminderText(tasks: PlanningTask[]): string {
	const all = store.snapshot().tasks;
	const done = all.filter((task) => task.status === "completed").length;
	return [
		"<system-reminder>",
		`You have an active task checklist (${done}/${all.length} done), but the task tools haven't been used in the last ${REMINDER_TURNS} turns.`,
		"If you are still working through it, call TaskUpdate to set the current item in_progress and mark items completed as you finish them.",
		"If the list has become stale or no longer matches your current work, clean it up with TaskUpdate (revise items, or set obsolete ones to status:deleted).",
		"Only act on this if it is relevant to your current work. This is a gentle reminder — never mention it to the user.",
		"",
		"Open tasks:",
		...tasks.map(formatTaskSummary),
		"</system-reminder>",
	].join("\n");
}

function updatePlanningTaskWidget(ctx: ExtensionContext | undefined): void {
	if (!ctx?.hasUI || !ctx.ui?.setWidget) return;
	const tasks = openTasks();
	if (tasks.length === 0) {
		ctx.ui.setWidget(TASK_WIDGET_KEY, undefined, { placement: "aboveEditor" });
		return;
	}
	const theme = ctx.ui.theme as any;
	const fg = (key: string, text: string) => (theme?.fg ? theme.fg(key, text) : text);
	const bold = (text: string) => (theme?.bold ? theme.bold(text) : text);
	const done = store.snapshot().tasks.filter((task) => task.status === "completed").length;
	const lines = [fg("toolTitle", bold(`Tasks ${done}/${store.snapshot().tasks.length} done`))];
	for (const task of tasks) lines.push(`  ${renderTaskLine(task, fg, bold)}`);
	ctx.ui.setWidget(TASK_WIDGET_KEY, lines, { placement: "aboveEditor" });
}

function renderTaskLine(
	task: PlanningTask,
	fg: (key: string, text: string) => string,
	bold: (text: string) => string,
): string {
	const label = task.status === "in_progress" && task.activeForm ? task.activeForm : task.subject;
	const icon = task.status === "in_progress" ? "◐" : "☐";
	const text = `${icon} #${displayId(task.id)} ${label}`;
	const base = task.status === "in_progress" ? fg("accent", bold(text)) : fg("muted", text);
	const owner = task.owner ? ` owner=${task.owner}` : "";
	const blockers = openBlockers(task);
	const blockedBy = blockers.length > 0 ? ` blocked_by=${blockers.map((id) => `#${displayId(id)}`).join(",")}` : "";
	return `${base}${fg("dim", `${owner}${blockedBy}`)}`;
}

function recordTaskSnapshot(pi: Pick<ExtensionAPI, "appendEntry">, store: TaskStore): Effect.Effect<void> {
	return Effect.sync(() => {
		pi.appendEntry("task-tools", taskSnapshotEvent(store));
	});
}

function recordIfPossible(pi: Pick<ExtensionAPI, "appendEntry"> | undefined, store: TaskStore): void {
	if (!pi) return;
	Effect.runSync(recordTaskSnapshot(pi, store));
}

function taskResult<TDetails>(text: string, details: TDetails): AgentToolResult<TDetails> {
	return { content: [{ type: "text", text }], details };
}

function taskError(error: unknown): AgentToolResult<{ error: string }> {
	return {
		content: [{ type: "text", text: error instanceof Error ? error.message : String(error) }],
		details: { error: error instanceof Error ? error.message : String(error) },
		isError: true,
	} as AgentToolResult<{ error: string }> & { isError: boolean };
}

function formatTaskList(tasks: PlanningTask[]): string {
	const all = store.snapshot().tasks;
	if (all.length === 0) return "No tasks found";
	return tasks.map(formatTaskSummary).join("\n");
}

function formatTaskSummary(task: PlanningTask): string {
	const owner = task.owner ? ` (${task.owner})` : "";
	const blockers = openBlockers(task);
	const blockedBy = blockers.length > 0 ? ` [blocked by ${blockers.map((id) => `#${displayId(id)}`).join(", ")}]` : "";
	return `#${displayId(task.id)} [${task.status}] ${task.subject}${owner}${blockedBy}`;
}

function formatTaskDetail(task: PlanningTask): string {
	const lines = [
		`Task #${displayId(task.id)}: ${task.subject}`,
		`Status: ${task.status}`,
		`Description: ${task.description ?? ""}`,
	];
	if (task.activeForm) lines.push(`Active form: ${task.activeForm}`);
	if (task.owner) lines.push(`Owner: ${task.owner}`);
	if (task.blockedBy.length > 0) lines.push(`Blocked by: ${task.blockedBy.map((id) => `#${displayId(id)}`).join(", ")}`);
	if (task.blocks.length > 0) lines.push(`Blocks: ${task.blocks.map((id) => `#${displayId(id)}`).join(", ")}`);
	if (task.metadata && Object.keys(task.metadata).length > 0) lines.push(`Metadata: ${JSON.stringify(task.metadata)}`);
	return lines.join("\n");
}

function openBlockers(task: PlanningTask): string[] {
	return task.blockedBy.filter((id) => store.get(id)?.status !== "completed");
}

function displayId(taskId: string): string {
	return taskId.replace(/^task-/, "");
}

