function registerPlanningTaskUi(pi: ExtensionAPI): void {
	const b5 = pi as B5ExtensionApi;
	if (typeof b5.registerMainPane !== "function") return;
	b5.registerMainPane(TASK_PANE_ID, (tui, theme, api) => new PlanningTasksPane(tui, theme, api.requestHide));
	if (typeof b5.registerFooter === "function" && typeof b5.showMainPane === "function") {
		b5.registerFooter(TASK_PANE_ID, {
			order: -6,
			visible: () => openTasks().length > 0,
			render: ({ theme, selected }) => planningTasksFooterText(theme, selected),
			onActivate: () => b5.showMainPane?.(TASK_PANE_ID),
		});
	}
}

function planningTasksFooterText(theme: ThemeLike, selected: boolean): string {
	const tasks = openTasks();
	if (tasks.length === 0) return "";
	const active = tasks.filter((task) => task.status === "in_progress").length;
	const marker = selected ? "▶ " : "● ";
	return theme.fg(selected ? "accent" : "dim", `${marker}${tasks.length} task${tasks.length === 1 ? "" : "s"}${active ? ` · ${active} active` : ""} · enter plan`);
}

