for(const f of files){try{const p=JSON.parse(fs.readFileSync(f));if(p.name&&!p.private)pub.push({name:p.name,dir:require("path").dirname(f)});}catch{}}
const missing=pub.filter(p=>!released.has(p.name));
console.log("publishable:",pub.length,"released:",released.size,"missing releases:",missing.length);
for(const m of missing){
  let secLen=0,ver="?";
  try{const cl=fs.readFileSync(m.dir+"/CHANGELOG.md","utf8");
    const lines=cl.split("\n");let c=0,buf=[];
    for(const l of lines){if(/^## /.test(l)){c++;if(c===1)ver=l;}if(c===1)buf.push(l);if(c===2)break;}
    secLen=buf.join("\n").length;
  }catch(e){ver="(no CHANGELOG)";}
  console.log(`  MISSING: ${m.name}  topEntry=${secLen} chars  ${ver}`);
}
'

