#!/usr/bin/env node
// Create one GitHub Release per just-published package, with the body capped
// under GitHub's 125000-char Release-body limit.
//
// Why this exists instead of changesets/action's built-in createGithubReleases:
// the action POSTs the package's raw changelog section as the Release body with
// no size guard. After an upstream sync dumps a large changelog under a single
// version heading, that one body exceeds 125000 chars, GitHub 422s
// ("body is too long"), and the whole publish job goes red — sometimes after it
// already published to the registry but before every Release was created,
// leaving packages without a Release. We truncate instead, so a Release is
// always created and the publish job never fails on changelog size.
//
// Usage: node create-github-releases.mjs '<publishedPackages JSON>'
//   publishedPackages: changesets/action `publishedPackages` output, e.g.
//   [{"name":"@valkyriweb/pi-agent-ui","version":"0.1.2"}]

import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { execFileSync } from "node:child_process";

const BODY_LIMIT = 124000; // < GitHub's 125000 hard cap, leaves room for the footer
const TRUNCATE_FOOTER =
  "\n\n…changelog truncated to fit GitHub's Release-body limit. " +
  "See the package's `CHANGELOG.md` for the full entry.";

const published = JSON.parse(process.argv[2] || "[]");
if (!Array.isArray(published) || published.length === 0) {
  console.log("No published packages — nothing to release.");
  process.exit(0);
}

// Map package name -> directory by scanning tracked package.json files.
const pkgFiles = execFileSync("git", ["ls-files", "**/package.json", "package.json"])
  .toString()
  .trim()
  .split("\n")
  .filter((f) => f && !f.includes("node_modules"));

const nameToDir = new Map();
for (const f of pkgFiles) {
  try {
    const pkg = JSON.parse(readFileSync(f, "utf8"));
    if (pkg.name) nameToDir.set(pkg.name, dirname(f));
  } catch {
    /* ignore unparseable package.json */
  }
}

// Extract the changelog section for `version` from a CHANGELOG.md body.
function changelogEntry(changelog, version) {
  const lines = changelog.split("\n");
  const out = [];
  let inEntry = false;
  for (const line of lines) {
    const heading = /^##\s+(.+?)\s*$/.exec(line);
    if (heading) {
      if (inEntry) break; // reached the next version
      if (heading[1] === version || heading[1] === `v${version}`) {
        inEntry = true;
        continue; // skip the heading itself; tag/title already carry the version
      }
    }
    if (inEntry) out.push(line);
  }
  return out.join("\n").trim();
}

function releaseExists(tag) {
  try {
    execFileSync("gh", ["release", "view", tag], { stdio: "ignore" });
    return true;
  } catch {
    return false;
  }
}

let created = 0;
let skipped = 0;
for (const { name, version } of published) {
  const tag = `${name}@${version}`;
  if (releaseExists(tag)) {
    console.log(`• ${tag} — release already exists, skipping`);
    skipped++;
    continue;
  }

  const dir = nameToDir.get(name);
  let body = "";
  const clPath = dir && join(dir, "CHANGELOG.md");
  if (clPath && existsSync(clPath)) {
    body = changelogEntry(readFileSync(clPath, "utf8"), version);
  }
  if (!body) body = `Release ${tag}.`;
  if (body.length > BODY_LIMIT) {
    body = body.slice(0, BODY_LIMIT - TRUNCATE_FOOTER.length) + TRUNCATE_FOOTER;
    console.log(`  (body truncated to ${body.length} chars)`);
  }

  execFileSync("gh", ["release", "create", tag, "--title", tag, "--notes", body], {
    stdio: "inherit",
  });
  console.log(`✓ ${tag} — release created`);
  created++;
}

console.log(`Done: ${created} created, ${skipped} skipped.`);

