/**
 * task-tools parameter schemas — two deliberately separate layers.
 *
 *   1. Declared wire schema (TypeBox). What `pi.registerTool({ parameters })`
 *      serialises into the model-facing `tools[]` JSON Schema. pi requires a
 *      TypeBox `TSchema` here and the emitted bytes are cache-critical: they
 *      must stay byte-identical within a session (these are deferLoading tools,
 *      activated on demand). We deliberately do NOT regenerate them from Effect
 *      Schema — Effect's JSONSchema.make emits a different shape and would shift
 *      the cached prefix. TypeBox stays the cache-stable *declared* schema; we
 *      never coerce by mutating it.
 *
 *   2. Runtime validation (Effect Schema). The typed decode/validation contract
 *      that runs in `execute`. `normalizeTaskDraft` is the tolerant-coercion
 *      boundary (unwrap legacy `{task}` wrappers, JSON.parse stringified args,
 *      map title→subject / body→description); after coercion the result is
 *      decoded *strictly* by Effect Schema, which surfaces typed decode errors
 *      (`TaskParamsError`). Coerce tolerantly at the boundary, validate strictly
 *      inside.
 */
import { Type } from "@sinclair/typebox";
import { Either, ParseResult, Schema } from "effect";

export const taskStatuses = ["pending", "in_progress", "completed"] as const;

export type TaskStatus = (typeof taskStatuses)[number];

// Accepted by task_update only (CC TaskUpdate parity): `deleted` permanently
// removes the record, so it is never a stored TaskStatus.
export const taskUpdateStatuses = [...taskStatuses, "deleted"] as const;

export type TaskUpdateStatus = (typeof taskUpdateStatuses)[number];

export interface PlanningTask {
	id: string;
	subject: string;
	description?: string;
	activeForm?: string;
	status: TaskStatus;
	owner?: string;
	metadata?: Record<string, unknown>;
	blockedBy: string[];
	blocks: string[];
	createdAt: number;
	updatedAt: number;
}

export interface TaskSnapshot {
	tasks: PlanningTask[];
}

// ── Declared wire schema (TypeBox, cache-stable) ────────────────────────────
// These objects are the model-facing JSON Schema pi puts in `tools[]`. Keep them
// byte-stable; do not regenerate from Effect Schema (see file header).

const subjectField = Type.Optional(
	Type.String({ description: "Imperative task title, e.g. 'Fix login redirect'. Required." }),
);
const descriptionField = Type.Optional(Type.String({ description: "Extra detail or acceptance notes." }));
const activeFormField = Type.Optional(
	Type.String({ description: "Present-continuous label shown while the task is in_progress, e.g. 'Designing auth schema'. Falls back to subject." }),
);
const blockedByField = Type.Optional(Type.Array(Type.String(), { description: "Task ids that must complete first." }));
const ownerField = Type.Optional(Type.String({ description: "Human label or agent runId responsible for the task." }));
const metadataField = Type.Optional(
	Type.Record(Type.String(), Type.Unknown(), { description: "Arbitrary metadata to attach to the task." }),
);

const TaskDraftObject = Type.Object({
	subject: Type.String({ description: "Short task title." }),
	description: descriptionField,
	activeForm: activeFormField,
	blockedBy: blockedByField,
	owner: ownerField,
	metadata: metadataField,
});

// Flat top-level params are the documented happy path (CC TodoWrite style: no
// wrapper object). The optional `task` field tolerates the legacy
// {task:{...}}/{task:"..."} shape so older callers and stringified input still
// work. normalizeTaskDraft enforces that a subject is ultimately present.
export const TaskCreateParams = Type.Object({
	subject: subjectField,
	description: descriptionField,
	activeForm: activeFormField,
	blockedBy: blockedByField,
	owner: ownerField,
	metadata: metadataField,
	task: Type.Optional(
		Type.Union([TaskDraftObject, Type.String()], {
			description: "Legacy/alternate form: a {subject, description?, ...} object or a plain string. Prefer the flat top-level fields above.",
		}),
	),
});

export const TaskGetParams = Type.Object({
	task_id: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Pi-compatible spelling." })),
	taskId: Type.Optional(Type.String({ description: "Task id, e.g. task-1. Claude Code-compatible spelling." })),
});

export const TaskUpdateParams = Type.Object({
	task_id: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Pi-compatible spelling." })),
	taskId: Type.Optional(Type.String({ description: "Task id to update, e.g. 'task-2'. Claude Code-compatible spelling." })),
	status: Type.Optional(
		Type.Union(
			taskUpdateStatuses.map((status) => Type.Literal(status)),
			{ description: "pending|in_progress|completed, or deleted to permanently remove the task." },
		),
	),
	subject: Type.Optional(Type.String({ description: "Replacement task title." })),

