206	/** Decode `input` against `schema`, throwing a typed `TaskParamsError` on failure. */
207	function decode<A, I>(schema: Schema.Schema<A, I>, input: unknown, what: string): A {
208		const result = Schema.decodeUnknownEither(schema)(input);
209		if (Either.isLeft(result)) {
210			throw new TaskParamsError(`Invalid ${what}: ${ParseResult.TreeFormatter.formatErrorSync(result.left)}`);
211		}
212		return result.right;
213	}
