215	export const decodeTaskGet = (input: unknown): TaskGetInput => decode(TaskGetSchema, normalizeTaskId(input, "task_get"), "task_get params");
216	export const decodeTaskUpdate = (input: unknown): TaskUpdateInput => decode(TaskUpdateSchema, normalizeTaskId(input, "task_update"), "task_update params");
217	export const decodeTaskListOptions = (input: unknown): TaskListInput => decode(TaskListSchema, input, "task_list params");
218	
219	function normalizeTaskId(input: unknown, toolName: string): Record<string, unknown> {
220		const loose = decode(LooseTaskIdSchema, input, `${toolName} params`);
221		const taskId = loose.task_id ?? loose.taskId;
222		if (!taskId?.trim()) throw new TaskParamsError(`${toolName} requires task_id (Pi) or taskId (Claude Code).`);
223		return { ...(input as Record<string, unknown>), task_id: taskId.trim() };
224	}
225	
226	/**
227	 * Coerce loose task_create params into a validated `TaskDraft`. Accepts the flat
228	 * top-level shape ({subject, description, ...}), a legacy {task:{...}} wrapper, a
229	 * stringified-JSON object, or a plain string (first line -> subject, rest ->
230	 * description). Maps `title`->`subject` and `body`->`description`. The coerced
231	 * result is then strictly validated by Effect Schema, surfacing a typed
232	 * `TaskParamsError` when no valid subject can be derived.
233	 */
234	export function normalizeTaskDraft(params: unknown): TaskDraft {
235		// Unwrap the legacy/alternate `task` field when the flat subject is absent.
236		if (params && typeof params === "object" && !Array.isArray(params)) {
237			const p = params as Record<string, unknown>;
238			const hasFlat = typeof p.subject === "string" || typeof p.title === "string";
239			if (!hasFlat && p.task !== undefined) return coerceDraft(p.task);
240		}
241		return coerceDraft(params);
242	}
243	
244	function coerceDraft(input: unknown): TaskDraft {
245		let value: unknown = input;
246		if (typeof value === "string") {
247			const trimmed = value.trim();
248			const parsed = trimmed.startsWith("{") ? tryParseJsonObject(trimmed) : undefined;
249			if (parsed) {
250				value = parsed;
251			} else {
252				const newline = trimmed.indexOf("\n");
253				const subject = (newline === -1 ? trimmed : trimmed.slice(0, newline)).trim();
254				const description = newline === -1 ? undefined : trimmed.slice(newline + 1).trim() || undefined;
255				return decode(TaskDraftSchema, { subject, description }, "task_create params");
256			}
257		}
258		if (!value || typeof value !== "object") {
259			throw new TaskParamsError("task_create requires a task object {subject, description?} or a string.");
260		}
261		const obj = value as Record<string, unknown>;
262		// title -> subject, body -> description alias mapping before strict validation.
263		const subject =
264			typeof obj.subject === "string" && obj.subject.trim()
265				? obj.subject.trim()
266				: typeof obj.title === "string" && obj.title.trim()
267					? obj.title.trim()
268					: "";
269		const description =
270			typeof obj.description === "string" ? obj.description.trim() || undefined
271				: typeof obj.body === "string" ? obj.body.trim() || undefined
272					: undefined;
273		return decode(
274			TaskDraftSchema,
275			{
276				subject,
277				description,
278				activeForm: typeof obj.activeForm === "string" ? obj.activeForm.trim() || undefined : undefined,
279				// Tolerant: drop a non-array blockedBy / non-string owner / non-object
280				// metadata here; strict decode below still validates whatever survives.
281				blockedBy: Array.isArray(obj.blockedBy) ? obj.blockedBy : undefined,
282				owner: typeof obj.owner === "string" ? obj.owner : undefined,
283				metadata:
284					obj.metadata && typeof obj.metadata === "object" && !Array.isArray(obj.metadata)
285						? (obj.metadata as Record<string, unknown>)
286						: undefined,
287			},
288			"task_create params",
289		);
290	}
291	
292	function tryParseJsonObject(text: string): Record<string, unknown> | undefined {
293		try {
294			const parsed = JSON.parse(text);
295			return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : undefined;
296		} catch {
297			return undefined;
298		}
299	}

