const restoredTools = {};
const restoredHandlers = {};
factory({ ...api, registerTool: (tool) => (restoredTools[tool.name] = tool), on: (event, handler) => (restoredHandlers[event] = handler) });
restoredHandlers.session_start({ type: "session_start", reason: "resume" }, ctx);
const restored = await restoredTools.TaskGet.execute("call", { taskId: "task-2" }, undefined, undefined, ctx);
assert.equal(restored.details.task.subject, "Build task CRUD");
assert(widgets.at(-1).value.some((line) => line.includes("#2 Build task CRUD")), "resume restores latest task checklist widget state");

const invalid = await call("TaskCreate", { subject: "Invalid", blockedBy: ["task-999"] });
assert.equal(invalid.isError, true);
assert.match(invalid.content[0].text, /Unknown dependency/);

const flat = await call("task_create", { subject: "Flat shape", description: "flat body" });
assert.equal(flat.details.task.id, "task-3", "lowercase task_create remains compatibility alias");
assert.equal(flat.details.task.subject, "Flat shape");
assert.equal(flat.details.task.description, "flat body");

const fromString = await call("task_create", { task: "String subject\nstring body line" });
assert.equal(fromString.details.task.subject, "String subject");
assert.equal(fromString.details.task.description, "string body line");

const fromJsonString = await call("task_create", { task: JSON.stringify({ title: "Title alias", body: "Body alias" }) });
assert.equal(fromJsonString.details.task.subject, "Title alias");
assert.equal(fromJsonString.details.task.description, "Body alias");

const withActive = await call("TaskCreate", { subject: "Design schema", activeForm: "Designing schema" });
assert.equal(withActive.details.task.activeForm, "Designing schema");
const activeId = withActive.details.task.id;
await call("TaskUpdate", { taskId: activeId, status: "in_progress" });
assert(widgets.at(-1).value.some((line) => line.includes(`◐ #${activeId.replace("task-", "")} Designing schema`)), "in-progress widget line uses activeForm as active verb");
const activeList = await call("TaskList", {});
assert.match(activeList.content[0].text, new RegExp(`#${activeId.replace("task-", "")} \\[in_progress\\] Design schema`), "TaskList summary keeps subject while widget uses activeForm");

const depA = (await call("TaskCreate", { subject: "Dep A" })).details.task.id;

