17		registerTool: (tool) => (handlers.tools[tool.name] = tool),
18		on: (event, handler) => (handlers[event] = handler),
19		appendEntry: (customType, data) => branch.push({ type: "custom", customType, data }),
20		registerMainPane: (id, factory) => panes.set(id, factory),
21		registerFooter: (id, spec) => footers.set(id, spec),
22		showMainPane: (id) => { shownPane = id; },
23	};
