114	const depA = (await call("TaskCreate", { subject: "Dep A" })).details.task.id;
115	const depB = (await call("TaskCreate", { subject: "Dep B" })).details.task.id;
116	const consumer = (await call("TaskCreate", { subject: "Consumer" })).details.task.id;
