17	type ThemeLike = ExtensionContext["ui"]["theme"];
18	type ExtensionMainPaneComponent = {
19		render(width: number): string[];
20		invalidate(): void;
21		handleInput(data: string): void;
22		onEscape?(): boolean | undefined;
23	};
24	type ExtensionMainPaneFactory = (tui: { requestRender(): void }, theme: ThemeLike, api: { payload: unknown; requestHide(): void }) => ExtensionMainPaneComponent;
25	type B5ExtensionApi = ExtensionAPI & {
26		registerMainPane?: (id: string, factory: ExtensionMainPaneFactory) => void;
27		registerFooter?: (id: string, spec: { order?: number; visible?: () => boolean; render(ctx: { theme: ThemeLike; selected: boolean; width: number }): string; onActivate(api: { close(): void }): void }) => void;
28		showMainPane?: (id: string, payload?: unknown) => void;
29	};
30	
31	export type PlanningTaskToolName =
32		| "TaskCreate"
33		| "TaskGet"
34		| "TaskUpdate"
35		| "TaskList"
36		| "task_create"
37		| "task_get"
38		| "task_update"
39		| "task_list";
40	
41	const TASK_WIDGET_KEY = "planning-tasks";
42	const TASK_PANE_ID = "planning-tasks";
43	
44	const promptGuidelines = [
45		"Use TaskCreate/TaskUpdate/TaskList as the live checklist for multi-step work; TodoWrite is legacy and should not be used in this profile.",
46		"Before updating a task after interruption, pivot, or stale state, read its latest state with TaskGet.",
47		"Mark a task in_progress before starting work and completed immediately after it is fully done; failing tests, blockers, or partial work stay in_progress.",
48		"When direction changes, update task subject/description/activeForm for still-relevant work and delete obsolete tasks with status:'deleted'.",
49		"Use blockedBy/addBlockedBy/addBlocks to model dependencies; TaskList shows open blockers, TaskGet shows full dependency detail.",
50		"Put agent run ids, workflow ids, background ids, or human labels in owner/metadata; do not reuse runtime ids as planning task ids.",
51		"Check TaskList before creating tasks to avoid duplicates; claim available work by setting owner.",
52	];
53	
54	let store = new TaskStore();
55	
56	// ── CC-style task reminder: append-only, cache-safe heartbeat ────────────────
57	// Claude Code keeps its task list "live" by re-injecting a <system-reminder>
58	// with the current list every ~10 idle turns (CC's TURNS_SINCE_WRITE /
59	// TURNS_BETWEEN_REMINDERS, both 10). Pi previously only painted a TUI widget plus
60	// a one-shot completion nudge, so once the original tool results scrolled out of
61	// context the list went dormant and the agent drifted onto other work. We port
62	// the heartbeat through the `context` hook, which is transient per-call (never
63	// written back to session history) and strictly APPEND-ONLY at the tail: the
64	// cached prefix (system prompt, tools, prior turns) stays byte-identical, so it
65	// never bursts the prompt cache. Disable with PI_TASK_REMINDER_DISABLED=1; tune
66	// the idle-turn threshold with PI_TASK_REMINDER_TURNS (default 10).
67	const REMINDER_DISABLED = process.env.PI_TASK_REMINDER_DISABLED === "1";
68	const REMINDER_TURNS = parsePositiveInt(process.env.PI_TASK_REMINDER_TURNS, 10);
69	
70	// Assistant turns since the agent last touched any Task* tool, and since the
71	// reminder last fired. Both must reach REMINDER_TURNS before a reminder is
72	// re-injected, mirroring CC's two-counter throttle.
73	let turnsSinceTaskTool = 0;
74	let turnsSinceReminder = 0;
75	
76	function parsePositiveInt(raw: string | undefined, fallback: number): number {
77		const value = Number(raw);
78		return Number.isInteger(value) && value > 0 ? value : fallback;
79	}
80	
81	function resetReminderCounters(): void {
82		turnsSinceTaskTool = 0;
83		turnsSinceReminder = 0;
84	}
85	
86	export function initPlanningTaskStoreFromEntries(entries: unknown[]): void {
87		store = TaskStore.fromEntries(entries);
88	}
89	
90	export function planningTaskStoreSnapshot() {
91		return store.snapshot();
92	}
93	
94	export async function executePlanningTaskTool(
95		name: PlanningTaskToolName,
96		params: unknown,
97		pi?: Pick<ExtensionAPI, "appendEntry">,
98		ctx?: ExtensionContext,
99	): Promise<AgentToolResult<unknown>> {
100		try {
101			// Any task-tool interaction counts as "the list is being used": reset the
102			// idle counter so the reminder heartbeat only fires when the agent has
103			// genuinely stopped touching the checklist.
104			turnsSinceTaskTool = 0;
105			switch (name) {
106				case "TaskCreate":
107				case "task_create": {
108					const task = store.create(normalizeTaskDraft(params));
109					recordIfPossible(pi, store);
110					updatePlanningTaskWidget(ctx);
111					return taskResult(`Task #${displayId(task.id)} created successfully: ${task.subject}`, { task, snapshot: store.snapshot() });
112				}
113				case "TaskGet":
114				case "task_get": {
115					const { task_id: taskId } = decodeTaskGet(params);
116					const task = store.get(taskId);
117					return taskResult(task ? formatTaskDetail(task) : "Task not found", { task: task ?? null });
118				}
119				case "TaskUpdate":
120				case "task_update": {
121					const { task_id: taskId, status, ...update } = decodeTaskUpdate(params);
122					if (status === "deleted") {
123						const task = store.delete(taskId);
124						recordIfPossible(pi, store);
125						updatePlanningTaskWidget(ctx);
126						return taskResult(`Deleted task #${displayId(task.id)}: ${task.subject}`, { task, snapshot: store.snapshot() });
127					}
128					const before = store.get(taskId);
129					const task = store.update(taskId, { ...update, status });
130					recordIfPossible(pi, store);
131					updatePlanningTaskWidget(ctx);
132					let text = `Updated task #${displayId(task.id)}`;
133					if (before && before.status !== task.status && task.status === "completed") {
134						text += "\nTask completed. Call TaskList now to find your next available task or see if your work unblocked others.";
135					}
136					return taskResult(text, { task, snapshot: store.snapshot() });
137				}
138				case "TaskList":
139				case "task_list": {
140					const tasks = store.list(decodeTaskListOptions(params));
141					return taskResult(formatTaskList(tasks), { tasks });
142				}
143			}
144		} catch (error) {
145			return taskError(error);
146		}
147	}
148	
149	export default function taskToolsExtension(pi: ExtensionAPI): void {
150		registerPlanningTaskUi(pi);
151		pi.on("session_start", (_event, ctx) => {
152			initPlanningTaskStoreFromEntries(ctx.sessionManager.getBranch());
153			resetReminderCounters();
154			updatePlanningTaskWidget(ctx);
155		});
156		pi.on("turn_start", () => {
157			turnsSinceTaskTool += 1;
158			turnsSinceReminder += 1;
159		});
160		pi.on("context", (event) => maybeInjectTaskReminder(event));
161		registerPlanningTaskTools(pi);
162	}
163	
164	function registerPlanningTaskUi(pi: ExtensionAPI): void {
165		const b5 = pi as B5ExtensionApi;
166		if (typeof b5.registerMainPane !== "function") return;
167		b5.registerMainPane(TASK_PANE_ID, (tui, theme, api) => new PlanningTasksPane(tui, theme, api.requestHide));
168		if (typeof b5.registerFooter === "function" && typeof b5.showMainPane === "function") {
169			b5.registerFooter(TASK_PANE_ID, {
170				order: -6,
171				visible: () => openTasks().length > 0,
172				render: ({ theme, selected }) => planningTasksFooterText(theme, selected),
173				onActivate: () => b5.showMainPane?.(TASK_PANE_ID),
174			});
175		}
176	}
177	
