1	import { mkdir, readFile, writeFile } from "node:fs/promises";
2	import { homedir } from "node:os";
3	import { dirname, join } from "node:path";
4	
5	// Slice 1: cache-stable profile injection (ported + consolidated from
6	// dream-memory's `pi-dream-memory.profile-base`).
7	//
8	// profile/** is global + cwd-independent, so it belongs in the cross-cwd
9	// cacheable BASE, not the per-cwd dynamic tail. A `systemPrompt:build` filter
10	// (priority 10) splices a byte-stable profile snapshot as the FIRST
11	// <project_instructions> block inside <project_context>. cache-base-prompt
12	// (priority 90, PI_EXTEND_BASE_PROMPT=1) then relocates that leading global run
13	// above SYSTEM_PROMPT_DYNAMIC_BOUNDARY into block0 (cached once cross-cwd). With
14	// the flag off the block harmlessly leads the dynamic tail (no regression).
15	//
16	// SOURCE = obsidian ~/obsidian/dream-memory/memory/profile/. We render a
17	// snapshot FILE (~/.pi/agent/dream-memory/profile-memory.md) from the CURATED
18	// profile index files only — the 00- briefing card + MEMORY.md — NOT the whole
19	// 80-note tree. The individual notes are for on-demand qmd recall; dumping them
20	// into the cached base would bloat every session with ~4.6k tokens of arbitrary
21	// lex-first notes. The obsidian consolidation routine (autoDream) curates those
22	// two files and calls renderProfileSnapshot() to refresh the snapshot, applying
23	// the instruction-refiner + progressive-disclosure skills so the base stays
24	// tight and pointer-based.
25	//
26	// CACHE: the snapshot file is loaded once per process + memoised → byte-stable
27	// across turns and cwds. The file changes only when consolidation refreshes it,
28	// so the base is identical across multiple sessions between consolidations. The
29	// filter is fail-safe: any divergence/error returns the input prompt unchanged.
30	
31	function wikiHome(): string {
32		return process.env.DREAM_WIKI_HOME ?? join(homedir(), "obsidian", "dream-memory");
33	}
34	function obsidianProfileDir(): string {
35		return join(wikiHome(), "memory", "profile");
36	}
37	export function profileSnapshotPath(): string {
38		return process.env.PI_MEMORY_PROFILE_SNAPSHOT ?? join(homedir(), ".pi", "agent", "dream-memory", "profile-memory.md");
39	}
40	
41	// Curated, deterministic order. Missing files are skipped. The 00- briefing card
42	// loads first (matches its lex-first design); MEMORY.md is the profile index.
43	const CURATED_PROFILE_FILES = ["00-pi-active-context.md", "MEMORY.md"];
44	const SNAPSHOT_MAX_BYTES = 12 * 1024; // hard safety cap on the cached base
45	
46	const PC_OPEN_TAG = "<project_context>";
47	
48	function blockOpen(): string {
49		return `<project_instructions path="${profileSnapshotPath()}">`;
50	}
51	
52	function stripFrontmatter(body: string): string {
53		return body.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");
54	}
55	
56	/**
