32	// @ts-expect-error - no d.ts for the sibling extension
33	import { __test__ as cacheBase } from "../../cache-base-prompt/index.mjs";
34	
35	const { BOUNDARY, extendBase } = cacheBase as { BOUNDARY: string; extendBase: (p: string) => string };
36	
