48		"---\nlast_dreamed_at: 2026-05-30\n---\n# Pi Active Context\nLuke prefers terse replies.\n",
49	);
50	writeFileSync(join(profileDir, "MEMORY.md"), "# Memory\nProvider routing: claude-bridge.\n");
