import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

// Slice 1: cache-stable profile injection (ported + consolidated from
// dream-memory's `pi-dream-memory.profile-base`).
//
// profile/** is global + cwd-independent, so it belongs in the cross-cwd
// cacheable BASE, not the per-cwd dynamic tail. A `systemPrompt:build` filter
// (priority 10) splices a byte-stable profile snapshot as the FIRST
// <project_instructions> block inside <project_context>. cache-base-prompt
// (priority 90, PI_EXTEND_BASE_PROMPT=1) then relocates that leading global run
// above SYSTEM_PROMPT_DYNAMIC_BOUNDARY into block0 (cached once cross-cwd). With
// the flag off the block harmlessly leads the dynamic tail (no regression).
//
// SOURCE = obsidian ~/obsidian/dream-memory/memory/profile/. We render a
// snapshot FILE (~/.pi/agent/dream-memory/profile-memory.md) from the CURATED
// profile index files only — the 00- briefing card + MEMORY.md — NOT the whole
// 80-note tree. The individual notes are for on-demand qmd recall; dumping them
// into the cached base would bloat every session with ~4.6k tokens of arbitrary
// lex-first notes. The obsidian consolidation routine (autoDream) curates those
// two files and calls renderProfileSnapshot() to refresh the snapshot, applying
// the instruction-refiner + progressive-disclosure skills so the base stays
// tight and pointer-based.
//
// CACHE: the snapshot file is loaded once per process + memoised → byte-stable
// across turns and cwds. The file changes only when consolidation refreshes it,
// so the base is identical across multiple sessions between consolidations. The
// filter is fail-safe: any divergence/error returns the input prompt unchanged.

function wikiHome(): string {
	return process.env.DREAM_WIKI_HOME ?? join(homedir(), "obsidian", "dream-memory");
}
function obsidianProfileDir(): string {
	return join(wikiHome(), "memory", "profile");
}
export function profileSnapshotPath(): string {
	return process.env.PI_MEMORY_PROFILE_SNAPSHOT ?? join(homedir(), ".pi", "agent", "dream-memory", "profile-memory.md");
}

// Curated, deterministic order. Missing files are skipped. The 00- briefing card
// loads first (matches its lex-first design); MEMORY.md is the profile index.
const CURATED_PROFILE_FILES = ["00-pi-active-context.md", "MEMORY.md"];
const SNAPSHOT_MAX_BYTES = 12 * 1024; // hard safety cap on the cached base

const PC_OPEN_TAG = "<project_context>";

function blockOpen(): string {
	return `<project_instructions path="${profileSnapshotPath()}">`;
}

function stripFrontmatter(body: string): string {
	return body.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");
}

/**
 * extendBase parses <project_instructions> blocks by non-greedy regex and keys
 * a path multiset off them; profile text carrying these tokens would corrupt
 * that parse, so such content must NOT enter the base — the filter falls back to
 * returning the prompt unchanged (no content loss, just no cross-cwd cache).
 */
export function isProfileBaseSafe(content: string): boolean {
	return !content.includes("</project_instructions>") && !content.includes('<project_instructions path="');
}

/**
 * Insert the profile block as the first <project_instructions> block inside
 * <project_context>, leading cache-base-prompt's contiguous global run.
 * Returns the input unchanged when profile is already present (idempotent), or
 * `null` when there is no <project_context> to splice into.
 */
export function injectProfileBlock(prompt: string, block: string): string | null {
	if (typeof prompt !== "string") return null;
	if (prompt.includes(blockOpen())) return prompt; // idempotent
	const pcOpen = prompt.indexOf(PC_OPEN_TAG);
	if (pcOpen === -1) return null;
	const firstBlock = prompt.indexOf('<project_instructions path="', pcOpen);
	const at = firstBlock !== -1 ? firstBlock : pcOpen + PC_OPEN_TAG.length + 1;
	return `${prompt.slice(0, at)}${block}\n\n${prompt.slice(at)}`;
}

/**
 * Render the snapshot from the curated obsidian profile index files and write it
 * to profileSnapshotPath(). Returns the rendered content ("" when no curated
 * files exist). Called by the obsidian consolidation routine (Slice 2) and the
 * one-time / self-heal regeneration. Drops the in-process memo so the next
 * getProfileSnapshot() re-reads.
 */
export async function renderProfileSnapshot(): Promise<string> {
	const dir = obsidianProfileDir();
	const blocks: string[] = [];
	let bytes = 0;
	for (const name of CURATED_PROFILE_FILES) {
		let body: string;
		try {
			body = stripFrontmatter(await readFile(join(dir, name), "utf8")).trim();
		} catch {
			continue; // missing file → skip
		}
		if (!body) continue;
		const block = `### profile/${name}\n\n${body}`;
		const sep = blocks.length ? 2 : 0;
		if (bytes + sep + Buffer.byteLength(block, "utf8") > SNAPSHOT_MAX_BYTES) break;
		blocks.push(block);
		bytes += sep + Buffer.byteLength(block, "utf8");
	}
	const content = blocks.join("\n\n");
	const path = profileSnapshotPath();
	await mkdir(dirname(path), { recursive: true });
	await writeFile(path, content ? `${content}\n` : "", "utf8");
	resetProfileSnapshotCache();
	return content;
}

type Snapshot = { block: string; content: string; safe: boolean };
let _snapshot: Snapshot | null | undefined;

/** Load + memoise the byte-stable profile snapshot. `null` = no profile content. */
export async function getProfileSnapshot(): Promise<Snapshot | null> {
	if (_snapshot !== undefined) return _snapshot;
	try {
		const trimmed = (await readFile(profileSnapshotPath(), "utf8")).trim();
		if (!trimmed) {
			_snapshot = null;
			return null;
		}
		_snapshot = {
			block: `${blockOpen()}\n${trimmed}\n</project_instructions>`,
			content: trimmed,
			safe: isProfileBaseSafe(trimmed),
		};
	} catch {
		_snapshot = null;
	}
	return _snapshot;
}

/**
 * Render the snapshot if it is missing OR older than the newest curated obsidian
 * profile file. No-op (byte-stable) when fresh, so multiple sessions between
 * consolidations share one base; the next session after an hourly autoDream run
 * re-renders. Called on session_start.
 */
export async function ensureProfileSnapshot(): Promise<void> {
	const { existsSync, statSync } = await import("node:fs");
	const snap = profileSnapshotPath();
	if (!existsSync(snap)) {
		await renderProfileSnapshot();
		return;
	}
	let snapMtime: number;
	try {
		snapMtime = statSync(snap).mtimeMs;
	} catch {
		await renderProfileSnapshot();
		return;
	}
	const dir = obsidianProfileDir();
	let newestSource = 0;
	for (const name of CURATED_PROFILE_FILES) {
		try {
			newestSource = Math.max(newestSource, statSync(join(dir, name)).mtimeMs);
		} catch {
			// missing curated file → ignore for staleness
		}
	}
	if (newestSource > snapMtime) await renderProfileSnapshot();
}

/** Drop the memoised snapshot (after a consolidation refresh or in tests). */
export function resetProfileSnapshotCache(): void {
	_snapshot = undefined;
}

