#!/usr/bin/env node
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { basename, dirname, extname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const defaultRoot = resolve(scriptDir, "..");
const repoRoot = resolve(readFlag("--root") ?? defaultRoot);

const capabilityPackages = {
  // Shared library (pure turn-source predicates), not a profile-loaded capability
  // — it is a transitive dependency of the extensions that import it, so it is
  // never listed in a profile manifest. Classified for every profile so any
  // consumer's profile is covered.
  "pi-turn-source": {
    profiles: ["full", "harness", "actions", "pod"],
    category: "agent-engine",
  },
  "pi-agents": {
    profiles: ["full"],
    category: "agent-engine",
  },
  "pi-agent-ui": {
    profiles: ["full"],
    category: "agent-ui",
  },
  "pi-observability": {
    profiles: ["full", "pod"],
    category: "observability",
  },
};

const extensionCatalog = {
  "pi-agents": { profiles: ["full"], category: "agent-engine" },
  "pi-agent-ui": { profiles: ["full"], category: "agent-ui" },
  "pi-observability": { profiles: ["full", "pod"], category: "observability" },
  advisor: { profiles: ["full"], category: "advisor" },
  "agent-view": { profiles: ["full"], category: "human-ux" },
  "boot-context-log": { profiles: ["full"], category: "human-ux" },
  "cache-base-prompt": { profiles: ["full", "harness", "actions"], category: "agent-engine" },
  "context-usage": { profiles: ["full"], category: "human-ux" },
  "codex-service-tier": { profiles: ["full"], category: "human-ux" },
  "computer-use": { profiles: ["full"], category: "human-ux" },
  "context-forking": { profiles: ["full"], category: "agent-engine" },
  "dream-memory": { profiles: ["full"], category: "memory" },
  "github-pr": { profiles: ["full"], category: "human-ux" },
  handoff: { profiles: ["full"], category: "human-ux" },
  "idle-return": { profiles: ["full"], category: "human-ux" },
  "intercom-cache-guard": { profiles: ["full"], category: "human-ux" },
  "large-input-externalizer": { profiles: ["full"], category: "human-ux" },
  "kilocode-provider": { profiles: ["full"], category: "provider" },
  "letta-shadow": { profiles: ["full"], category: "memory" },
  "mem0-shadow": { profiles: ["full"], category: "memory" },
  monitor: { profiles: ["full"], category: "human-ux" },
  "native-tool-overrides": { profiles: ["full", "harness", "actions"], category: "tool-discovery" },
  "openclaw-adaptor": { profiles: ["full", "harness"], category: "tool-discovery" },
  notify: { profiles: ["full"], category: "human-ux" },
  "paperclip-cost-forwarder": { profiles: ["full"], category: "observability" },
  "pi-backpressure": { profiles: ["full"], category: "agent-engine" },
  "pi-goal": { profiles: ["full"], category: "goal" },
  "pi-memory": { profiles: ["full"], category: "memory" },
  "pi-routine": { profiles: ["full"], category: "routine" },
  "pi-semantic-grep": { profiles: ["full"], category: "human-ux" },
  "pi-session-todo": { profiles: [], category: "legacy" },
  "pi-recap": { profiles: ["full"], category: "human-ux" },
  "pi-thinking-keywords": { profiles: ["full"], category: "human-ux" },
  "pi-ask-user-question": { profiles: ["full"], category: "human-ux" },
  "pi-agent-panel": { profiles: ["full"], category: "human-ux" },
  "pi-mode": { profiles: ["full"], category: "human-ux" },
  "pi-worktree": { profiles: ["full"], category: "agent-engine" },
  // Deterministic multi-agent orchestrator (Workflow tool); an agent-engine
  // primitive, not a scheduled routine. Allowed in `actions` so the agentic
  // PR-review gate can drive it headlessly in CI. See docs/pr-review-gate.md.
  "pi-workflow": { profiles: ["full", "actions"], category: "agent-engine" },
  "session-title": { profiles: ["full"], category: "human-ux" },
  "skill-loader": { profiles: ["full", "harness", "actions"], category: "dynamic-skill-loader" },
  "syntax-input": { profiles: ["full"], category: "human-ux" },
  // Durable task/checklist primitive (TaskCreate/TaskUpdate). Distinct from the
  // autonomous goal loop (pi-goal, category "goal"), so it gets its own "task"
  // category and is allowed in the goal-loop-free `actions` profile.
  "task-tools": { profiles: ["full", "actions"], category: "task" },
  "time-context": { profiles: ["full"], category: "human-ux" },
  tokenjuice: { profiles: ["full"], category: "memory" },
  "tool-search": { profiles: ["full", "harness", "actions"], category: "tool-discovery" },
  "usage-soft-cap": { profiles: ["full"], category: "human-ux" },
  observability: { profiles: ["full", "harness", "pod"], category: "observability" },
  "observability/pi-opik-cli-bridge": { profiles: ["full", "pod"], category: "observability" },
  "observability/pi-otel-exporter": { profiles: ["full", "harness", "pod"], category: "observability" },
};

const profiles = {
  full: {
    packagePath: "packages/my-pi-full/package.json",
    forbiddenCategories: new Set(),
    forbiddenPackages: new Set(),
  },
  harness: {
    packagePath: "packages/my-pi-harness/package.json",
    forbiddenCategories: new Set(["agent-ui", "human-ux"]),
    forbiddenPackages: new Set(["pi-agents", "pi-agent-ui"]),
  },
  actions: {
    // Lean CI/automation profile: harness tooling minus the OpenClaw adaptor,
    // plus persistent task tracking. No memory, routine, goal-loop, advisor,
    // or UI.
    packagePath: "packages/my-pi-actions/package.json",
    forbiddenCategories: new Set([
      "memory",
      "routine",
      "goal",
      "advisor",
      "agent-ui",
      "human-ux",
    ]),
    forbiddenPackages: new Set(["pi-agents", "pi-agent-ui"]),
  },
  pod: {
    packagePath: "packages/my-pi-pod/package.json",
    forbiddenCategories: new Set([
      "agent-engine",
      "agent-ui",
      "memory",
      "advisor",
      "routine",
      "goal",
      "task",
      "dynamic-skill-loader",
      "human-ux",
    ]),
    forbiddenPackages: new Set(["pi-agents", "pi-agent-ui"]),
  },
};

const errors = [];
const warnings = [];
const summary = {};
const profileManifests = loadProfileManifests();
const discoveredExtensions = discoverExtensionIds(profileManifests);

checkClassifiedCapabilities();
checkClassifiedExtensions(discoveredExtensions);
checkProfileMembership(profileManifests);
printSummary(summary, errors, warnings);

if (errors.length > 0) process.exit(1);

function readFlag(name) {
  const index = process.argv.indexOf(name);
  return index === -1 ? null : process.argv[index + 1] ?? null;
}

function discoverExtensionIds(manifests) {
  const ids = new Set();
  const extensionsRoot = join(repoRoot, "extensions");

  if (existsSync(extensionsRoot)) {
    for (const entry of readdirSync(extensionsRoot, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (entry.name === "node_modules" || entry.name === "third-party") continue;
      if (existsSync(join(extensionsRoot, entry.name, "package.json"))) ids.add(entry.name);
    }
  }

  const rootPackage = readJson(join(repoRoot, "package.json"));
  for (const extension of rootPackage?.pi?.extensions ?? []) {
    const id = extensionIdFromPath(extensionPath(extension));
    if (id) ids.add(id);
  }

  for (const manifest of Object.values(manifests)) {
    for (const extension of manifest.extensions) {
      const id = extensionIdFromPath(extensionPath(extension));
      if (id) ids.add(id);
    }
  }

  return [...ids].sort();
}

function loadProfileManifests() {
  const manifests = {};
  for (const [profileName, profile] of Object.entries(profiles)) {
    const packagePath = join(repoRoot, profile.packagePath);
    if (!existsSync(packagePath)) {
      errors.push(`${profileName}: missing profile manifest ${profile.packagePath}`);
      manifests[profileName] = { packages: [], extensions: [] };
      continue;
    }

    const manifest = readJson(packagePath);
    manifests[profileName] = {
      packages: (manifest?.pi?.packages ?? []).map(packageIdFromPath),
      extensions: manifest?.pi?.extensions ?? [],
    };
  }
  return manifests;
}

function checkClassifiedCapabilities() {
  for (const packageName of discoverCapabilityPackageIds()) {
    if (!capabilityPackages[packageName]) errors.push(`${packageName}: capability package is unclassified`);
  }
}

function discoverCapabilityPackageIds() {
  const expected = new Set(Object.keys(capabilityPackages));
  const packagesRoot = join(repoRoot, "packages");
  if (!existsSync(packagesRoot)) return [...expected].sort();

  for (const entry of readdirSync(packagesRoot, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const packagePath = join(packagesRoot, entry.name, "package.json");
    if (!existsSync(packagePath)) continue;
    if (entry.name.startsWith("pi-") && !entry.name.startsWith("my-pi-")) expected.add(entry.name);
  }

  return [...expected].sort();
}

function checkClassifiedExtensions(extensionIds) {
  for (const extensionId of extensionIds) {
    if (!extensionCatalog[extensionId]) errors.push(`${extensionId}: extension is unclassified`);
  }
}

function checkProfileMembership(manifests) {
  for (const [profileName, manifest] of Object.entries(manifests)) {
    summary[profileName] = { packages: manifest.packages, extensions: [] };

    for (const packageName of manifest.packages) {
      const classification = capabilityPackages[packageName];
      if (!classification) {
        errors.push(`${profileName}: package ${packageName} is unclassified`);
        continue;
      }
      if (!classification.profiles.includes(profileName)) {
        errors.push(`${profileName}: package ${packageName} is classified for ${classification.profiles.join(", ")}, not ${profileName}`);
      }
      checkForbiddenPackage(profileName, packageName, classification.category);
    }

    for (const extension of manifest.extensions) {
      const rawPath = extensionPath(extension);
      const extensionId = extensionIdFromPath(rawPath);
      if (!extensionId) {
        errors.push(`${profileName}: cannot identify extension ${JSON.stringify(extension)}`);
        continue;
      }

      summary[profileName].extensions.push(formatExtension(extension));
      const classification = extensionCatalog[extensionId];
      if (!classification) {
        errors.push(`${profileName}: extension ${extensionId} is unclassified`);
        continue;
      }
      if (!classification.profiles.includes(profileName)) {
        errors.push(`${profileName}: extension ${extensionId} is classified for ${classification.profiles.join(", ")}, not ${profileName}`);
      }
      checkForbiddenExtension(profileName, extensionId, classification.category);
    }
  }
}

function checkForbiddenPackage(profileName, packageName, category) {
  const profile = profiles[profileName];
  if (profile.forbiddenPackages.has(packageName)) {
    errors.push(`${profileName}: package ${packageName} is forbidden`);
  }
  if (profile.forbiddenCategories.has(category)) {
    errors.push(`${profileName}: package ${packageName} has forbidden category ${category}`);
  }
}

function checkForbiddenExtension(profileName, extensionId, category) {
  const profile = profiles[profileName];
  if (profile.forbiddenCategories.has(category)) {
    errors.push(`${profileName}: extension ${extensionId} has forbidden category ${category}`);
  }
}

function extensionPath(extension) {
  return typeof extension === "string" ? extension : extension?.path;
}

function extensionIdFromPath(rawPath) {
  if (!rawPath || typeof rawPath !== "string") return null;
  const normalized = rawPath.replaceAll("\\", "/");
  const parts = normalized.split("/").filter(Boolean);

  // Capability packages live at packages/<name>/src/... and are referenced
  // from profile manifests as ../<name>/src/... (the validator resolves
  // profile manifests from packages/my-pi-*/). Treat the first non-".."
  // segment as the package id when the path passes through `packages/` or
  // the leading `../` parent traversal.
  const packagesIndex = parts.lastIndexOf("packages");
  if (packagesIndex !== -1 && parts[packagesIndex + 1]) {
    return parts[packagesIndex + 1];
  }
  if (parts[0] === ".." && parts[1] && parts[1] !== "..") {
    return parts[1];
  }

  const extensionsIndex = parts.lastIndexOf("extensions");
  const relevant = extensionsIndex === -1 ? parts : parts.slice(extensionsIndex + 1);
  if (relevant[0] === "observability" && relevant[1]) return `observability/${basename(relevant.at(-1), extname(relevant.at(-1)))}`;
  return relevant[0] ?? null;
}

function packageIdFromPath(rawPath) {
  if (typeof rawPath !== "string") return "<invalid-package-entry>";
  return basename(rawPath);
}

function formatExtension(extension) {
  const rawPath = extensionPath(extension);
  if (typeof extension === "string") return rawPath;
  const load = extension?.load ? ` (${extension.load})` : "";
  return `${rawPath}${load}`;
}

function readJson(path) {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch (error) {
    errors.push(`${relative(repoRoot, path)}: ${error.message}`);
    return null;
  }
}

function printSummary(profilesSummary, validationErrors, validationWarnings) {
  console.log("Pi runtime profile membership\n");
  for (const profileName of Object.keys(profiles)) {
    const membership = profilesSummary[profileName] ?? { packages: [], extensions: [] };
    console.log(`${profileName}:`);
    console.log(`  packages: ${membership.packages.length > 0 ? membership.packages.join(", ") : "(none)"}`);
    console.log("  extensions:");
    if (membership.extensions.length === 0) {
      console.log("    (none)");
    } else {
      for (const extension of membership.extensions) console.log(`    - ${extension}`);
    }
