  bash: 8_000,
  bashOutput: 8_000,
  lsFind: 20_000,
  grepExec: 32_000,
  agent: 50_000,
};

const TOOL_CLASS = {
  bash: "bash",
  Bash: "bash",
  bash_output: "bashOutput",
  BashOutput: "bashOutput",
  ls: "lsFind",
  Ls: "lsFind",
  find: "lsFind",
  Find: "lsFind",
  grep: "grepExec",
  Grep: "grepExec",
  exec_command: "grepExec",
  write_stdin: "grepExec",
  agent: "agent",
  Agent: "agent",
  Task: "agent",
};

