process.env.PI_CODING_AGENT_DIR = testAgentDir;
process.env.PI_TOKENJUICE_RAW_DIR = testRawDir;
delete process.env.PI_TOKENJUICE_ENABLED;
delete process.env.PI_TOKENJUICE_MIN_VISIBLE_CHARS;
delete process.env.PI_TOKENJUICE_REQUIRE_RAW_RECOVERY;
resetSettingsCache();

function createHost() {
  const handlers = new Map();
  wrappedRegister({
    on(name, handler) {
      handlers.set(name, handler);
    },
    registerCommand() {},
    appendEntry() {},
  });
  const toolResult = handlers.get("tool_result");
  assert.equal(typeof toolResult, "function");
  return toolResult;
}

function createContext({ source = "interactive", provider = "openai-codex", id = "gpt-5.5" } = {}) {
  const cwd = mkdtempSync(join(tmpdir(), "tokenjuice-cwd-"));
  return {
    cwd,
    source,
    model: { provider, id },
    hasUI: false,
    ui: { notify() {} },
    sessionManager: {
      getHeader: () => ({ cwd }),
      getCwd: () => cwd,
      getEntries: () => [],
      getBranch: () => [],
    },
  };
}

function outputOfChars(chars, label = "line") {
  const line = `${label}: ${"x".repeat(90)}`;
  return Array.from({ length: Math.ceil(chars / (line.length + 1)) }, (_, i) => `${label}-${i}: ${"x".repeat(90)}`)
    .join("\n")
    .slice(0, chars);
}

async function runToolResult(event, ctx = createContext()) {
  const toolResult = createHost();
  return toolResult(
    {
      content: [{ type: "text", text: outputOfChars(65_000, event.toolName) }],
      details: {},
      isError: false,
      ...event,
    },
    ctx,
  );
}

try {
  // 1. Above-threshold exec compacts AND the raw file is recoverable from the
  //    durable raw dir (relocated out of the bundle's /tmp dir), with every
  //    path mention rewritten.
  const compacted = await runToolResult({ toolName: "exec_command", input: { cmd: "rg openclaw" } });
  assert.equal(compacted?.details?.tokenjuice?.compacted, true);
  const rawPath = compacted.details.tokenjuice.rawPath;
  assert.ok(rawPath, "compacted result must carry rawPath");
  assert.ok(rawPath.startsWith(testRawDir), `rawPath relocated into PI_TOKENJUICE_RAW_DIR (got ${rawPath})`);
  assert.ok(existsSync(rawPath), "raw recovery file exists");
  assert.ok(readFileSync(rawPath, "utf8").includes("exec_command-0:"), "raw file holds the original output");
  assert.ok(compacted.content[0].text.includes(rawPath), "notice text points at the relocated raw file");

  // 2. Below the 32k grep/exec floor → no compaction at all.
  const small = await runToolResult({
    toolName: "exec_command",
    input: { cmd: "rg openclaw" },
    content: [{ type: "text", text: outputOfChars(10_000, "exec_command") }],
  });
  assert.equal(small, undefined);

  // 3. Evidence-bearing command patterns never compact, however large.
  for (const cmd of ["pnpm test --filter pi", "npx tsc --noEmit", "git diff main...HEAD", "npm run build"]) {
    const exempt = await runToolResult({ toolName: "exec_command", input: { cmd } });
    assert.equal(exempt, undefined, `command should be exempt: ${cmd}`);
  }

  // 4. Kill switch: PI_TOKENJUICE_ENABLED=0 → wrapper is a no-op.
  process.env.PI_TOKENJUICE_ENABLED = "0";
  assert.equal(await runToolResult({ toolName: "exec_command", input: { cmd: "rg openclaw" } }), undefined);
  delete process.env.PI_TOKENJUICE_ENABLED;

  // 5. Agent results are exempt initially (the bundle alone would compact a
  //    worker agent — see tool-result-hook.test.mjs — the policy blocks it).
  assert.equal(
    await runToolResult({ toolName: "Agent", input: { subagent_type: "worker", task: "fix files" } }),
    undefined,
  );

  // 6. Bundle-level exemptions stay intact through the wrapper.
  assert.equal(
    await runToolResult({ toolName: "Agent", input: { subagent_type: "explore", task: "map files" } }),
    undefined,
  );
  assert.equal(await runToolResult({ toolName: "web_fetch", input: { url: "https://example.test" } }), undefined);

  // 7. No double compaction when a tokenjuice notice is already present.
  const noticed = await runToolResult({
    toolName: "exec_command",
    input: { cmd: "rg openclaw" },
    content: [{ type: "text", text: `${outputOfChars(40_000, "exec_command")}\n[tokenjuice compacted exec_command output]` }],
  });
  assert.equal(noticed, undefined);

  // 8. Raw-recovery guarantee (unit): a compaction without a readable raw file
  //    is dropped under requireRawRecovery, kept only when explicitly waived.
  const orphan = () => ({
    content: [{ type: "text", text: "compacted notice" }],
    details: { tokenjuice: { compacted: true, rawPath: join(testRawDir, "missing-raw.txt") } },
  });
  assert.equal(enforceRawRecovery(orphan(), { requireRawRecovery: true, rawDir: testRawDir }), undefined);
  assert.notEqual(enforceRawRecovery(orphan(), { requireRawRecovery: false, rawDir: testRawDir }), undefined);
  const pathless = () => ({ content: [], details: { tokenjuice: { compacted: true } } });
  assert.equal(enforceRawRecovery(pathless(), { requireRawRecovery: true, rawDir: testRawDir }), undefined);

  // 9. Exempt-command matcher sanity.
  assert.equal(isExemptCommand("cargo test -p pi"), true);
  assert.equal(isExemptCommand("kubectl logs deploy/bridge"), true);
  assert.equal(isExemptCommand("rg openclaw src/"), false);

  console.log("tokenjuice policy contract: all assertions passed");
} finally {
  for (const [key, value] of Object.entries(previousEnv)) {
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
  }
  rmSync(testAgentDir, { recursive: true, force: true });
  rmSync(testRawDir, { recursive: true, force: true });
}

