#!/usr/bin/env node
// Guards oracle risk #7 (generated-bundle drift): `tokenjuice install pi`
// writes a real file to ~/.pi/agent/extensions/tokenjuice.js, so the bundle
// you review in-repo and the bundle Pi runs can silently diverge. This gate
// fails when the runtime install exists but is not byte-identical to the
// canonical vendored bundle. Absent/disabled runtime install passes (the
// canary profile loads the canonical copy directly).
import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const canonicalPath = join(repoRoot, "extensions", "tokenjuice", "tokenjuice.generated.js");
const runtimePath = process.env.PI_TOKENJUICE_RUNTIME_PATH ?? join(homedir(), ".pi", "agent", "extensions", "tokenjuice.js");

const sha = (path) => createHash("sha256").update(readFileSync(path)).digest("hex");

if (!existsSync(runtimePath)) {
  console.log(`tokenjuice runtime: not installed at ${runtimePath} — ok (canary loads the canonical copy)`);
  process.exit(0);
}

const canonical = sha(canonicalPath);
const runtime = sha(runtimePath);
if (canonical !== runtime) {
  console.error("tokenjuice runtime DRIFT detected:");
  console.error(`  canonical ${canonicalPath}\n    sha256 ${canonical}`);
  console.error(`  runtime   ${runtimePath}\n    sha256 ${runtime}`);
  console.error("Re-vendor (copy the runtime file back and review) or reinstall from the canonical bundle.");
  process.exit(1);
}
console.log("tokenjuice runtime: byte-identical to the canonical bundle — ok");

