/**
 * profile-base.test.ts — Slice 1. Proves pi-memory's profile-base injection is a
 * cross-cwd cacheable unit rendered from the curated obsidian profile files,
 * without dropping memory content. Runs against the LOADED pi-memory module
 * (the old dream-memory spec tested an unloaded extension → false green).
 *
 * Asserts:
 *   - renderProfileSnapshot pulls ONLY the curated index files (00- card +
 *     MEMORY.md), strips frontmatter, and excludes recall-only notes.
 *   - the snapshot read is memoised + byte-stable.
 *   - injectProfileBlock leads <project_context>, is idempotent, drops no bytes.
 *   - extendBase relocates the profile above the boundary and the cacheable base
 *     is BYTE-IDENTICAL across two cwds (cross-cwd cache) with no content loss.
 *   - flag-off (extendBase never runs) is harmless.
 */

import { afterAll, describe, expect, test } from "bun:test";
import { existsSync, mkdirSync, mkdtempSync, rmSync, statSync, utimesSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";

import {
	ensureProfileSnapshot,
	getProfileSnapshot,
	injectProfileBlock,
	isProfileBaseSafe,
	profileSnapshotPath,
	renderProfileSnapshot,
	resetProfileSnapshotCache,
} from "../src/profile-base.js";
// cache-base-prompt is plain ESM (.mjs) with no type declarations.
// @ts-expect-error - no d.ts for the sibling extension
import { __test__ as cacheBase } from "../../cache-base-prompt/index.mjs";

const { BOUNDARY, extendBase } = cacheBase as { BOUNDARY: string; extendBase: (p: string) => string };

// Isolate the obsidian source tree + snapshot file in a temp dir.
const tmp = mkdtempSync(join(tmpdir(), "pi-memory-profile-"));
const wiki = join(tmp, "obsidian", "dream-memory");
const profileDir = join(wiki, "memory", "profile");
// extendBase only relocates blocks under its global prefixes (~/.pi/agent/),
// matching the real snapshot location — so the test snapshot lives there too
// (uniquely named, cleaned up). The obsidian SOURCE stays in the temp tree.
const snapPath = join(homedir(), ".pi", "agent", "dream-memory", `profile-memory.test-${process.pid}.md`);
mkdirSync(profileDir, { recursive: true });
writeFileSync(
	join(profileDir, "00-pi-active-context.md"),
	"---\nlast_dreamed_at: 2026-05-30\n---\n# Pi Active Context\nLuke prefers terse replies.\n",
);
writeFileSync(join(profileDir, "MEMORY.md"), "# Memory\nProvider routing: claude-bridge.\n");
// A non-curated note that must NOT enter the cached base snapshot.
writeFileSync(join(profileDir, "agent-random-note.md"), "noise that should stay recall-only\n");
mkdirSync(join(homedir(), ".pi", "agent", "dream-memory"), { recursive: true });
process.env.DREAM_WIKI_HOME = wiki;
process.env.PI_MEMORY_PROFILE_SNAPSHOT = snapPath;
resetProfileSnapshotCache();
afterAll(() => {
	try {
		rmSync(snapPath, { force: true });
		rmSync(tmp, { recursive: true, force: true });
	} catch {}
});

const HOME = process.env.HOME ?? "/Users/luke";

function buildPrompt(cwdBody: string): string {
	return [
		"You are an expert coding assistant.",
		"",
		BOUNDARY,
		"",
		"<project_context>",
		"",
		`<project_instructions path="${HOME}/.pi/agent/AGENTS.md">`,
		"global harness rules",
		"</project_instructions>",
		"",
		`<project_instructions path="${HOME}/Projects/personal/some-repo/AGENTS.md">`,
		cwdBody,
		"</project_instructions>",
		"",
		"</project_context>",
		"",
		"Current date: 2026-05-29",
	].join("\n");
}

function baseSlice(prompt: string): string {
	const i = prompt.indexOf(BOUNDARY);
	return prompt.slice(0, i);
}

describe("pi-memory profile-base: snapshot render (source = obsidian curated files)", () => {
	test("renders only curated index files, strips frontmatter, excludes recall-only notes", async () => {
		const content = await renderProfileSnapshot();
		expect(content).toContain("### profile/00-pi-active-context.md");
		expect(content).toContain("Luke prefers terse replies");
		expect(content).toContain("### profile/MEMORY.md");
		expect(content).toContain("Provider routing: claude-bridge");
		expect(content).not.toContain("last_dreamed_at"); // frontmatter stripped
		expect(content).not.toContain("noise that should stay recall-only"); // non-curated excluded
		expect(existsSync(snapPath)).toBe(true);
	});

	test("snapshot read is memoised + byte-stable", async () => {
		await renderProfileSnapshot();
		const a = await getProfileSnapshot();
		const b = await getProfileSnapshot();
		expect(a).toBe(b); // same memoised object across reads
		expect(a?.safe).toBe(true);
		expect(a?.block.startsWith(`<project_instructions path="${snapPath}">`)).toBe(true);
	});

	test("unchanged content skips the rewrite; write goes through temp+rename (no partial reads)", async () => {
		await renderProfileSnapshot();
		const before = statSync(snapPath).mtimeMs;
		await renderProfileSnapshot(); // identical content → no fs mutation at all
		expect(statSync(snapPath).mtimeMs).toBe(before);
		// the atomic-write temp file never lingers
		expect(existsSync(`${snapPath}.tmp-${process.pid}`)).toBe(false);
	});
});

describe("pi-memory profile-base: injection", () => {
	test("inserts profile as the FIRST project_instructions block, idempotent, no byte loss", async () => {
		await renderProfileSnapshot();
		const snap = (await getProfileSnapshot())!;
		const input = buildPrompt("cwd A");
		const out = injectProfileBlock(input, snap.block)!;
		const pcOpen = out.indexOf("<project_context>");
		const profileAt = out.indexOf(`<project_instructions path="${snapPath}">`);
		const firstGlobal = out.indexOf(`<project_instructions path="${HOME}/.pi/agent/AGENTS.md">`);
		expect(profileAt).toBeGreaterThan(pcOpen);
		expect(profileAt).toBeLessThan(firstGlobal);
		expect(injectProfileBlock(out, snap.block)).toBe(out); // idempotent
		expect(out.length).toBe(input.length + snap.block.length + 2); // no byte loss
	});

	test("returns null without <project_context>; isProfileBaseSafe rejects nested tags", () => {
		expect(injectProfileBlock("no project context", "block")).toBeNull();
		expect(isProfileBaseSafe("plain markdown")).toBe(true);
		expect(isProfileBaseSafe("oops </project_instructions> mid-text")).toBe(false);
		expect(isProfileBaseSafe('nested <project_instructions path="x"> tag')).toBe(false);
	});

	test("isProfileBaseSafe rejects every prompt-structure delimiter, not just project_instructions", () => {
		for (const token of [
			"<project_context>",
			"</project_context>",
			"__PI_SYSTEM_PROMPT_DYNAMIC_BOUNDARY__", // the marker literal
