describe("pi-memory profile-base: cross-cwd cache via extendBase", () => {
	test("(a) cacheable base is BYTE-IDENTICAL across two cwds; (b) no content dropped", async () => {
		await renderProfileSnapshot();
		const snap = (await getProfileSnapshot())!;
		const baseA = extendBase(injectProfileBlock(buildPrompt("CWD-A-only"), snap.block)!);
		const baseB = extendBase(injectProfileBlock(buildPrompt("totally different B"), snap.block)!);

		// profile pulled above the boundary into the base
		expect(baseA.indexOf(snapPath)).toBeGreaterThanOrEqual(0);
		expect(baseA.indexOf(BOUNDARY)).toBeGreaterThan(baseA.indexOf(snapPath));
		// (a) cross-cwd byte identity of the base
		expect(baseSlice(baseA)).toBe(baseSlice(baseB));
