describe("pi-memory profile-base: ensureProfileSnapshot tracks consolidation", () => {
	test("re-renders when an obsidian profile file is newer; no-op when fresh", async () => {
		await renderProfileSnapshot();
		const nowSec = Date.now() / 1000;
		// Pin the snapshot in the past, then a (simulated) consolidation writes a
		// newer card — both still before now, mirroring the real source→render order.
		utimesSync(snapPath, nowSec - 100, nowSec - 100);
		writeFileSync(join(profileDir, "00-pi-active-context.md"), "# Pi Active Context\nNEW consolidated line.\n");
		utimesSync(join(profileDir, "00-pi-active-context.md"), nowSec - 50, nowSec - 50);

		await ensureProfileSnapshot(); // source newer → re-render (snapshot mtime → now)
		resetProfileSnapshotCache();
		expect((await getProfileSnapshot())?.content).toContain("NEW consolidated line");

		// snapshot is now newer than the source → ensure is a no-op
		const fresh = statSync(snapPath).mtimeMs;
