toolUseResult.originalFile:
// Cache-stability smoke (oracle Diff 4), extension-surface level: tokenjuice
// can only influence appended tool results. It must never touch the host APIs
// that shape the cached prompt prefix (params.system) or the tools[] array —
// no registerTool / setActiveTools / system-prompt filters — whether the
// policy gate is enabled or disabled, before and after compactions run.
// (Full-profile byte-capture of params.system/tools[] lives in the harness
// cache gates, e.g. `npm run test:claude-bridge:cache`.)
import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import wrappedRegister from "./index.js";

const FORBIDDEN_HOST_APIS = [
  "registerTool",
  "setActiveTools",
  "getActiveTools",
  "setSystemPrompt",
  "registerProvider",
  "hooks",
  "addFilter",
  "applyFilters",
];

const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
const previousEnabled = process.env.PI_TOKENJUICE_ENABLED;
const previousRawDir = process.env.PI_TOKENJUICE_RAW_DIR;
const testAgentDir = mkdtempSync(join(tmpdir(), "tokenjuice-agent-"));
const testRawDir = mkdtempSync(join(tmpdir(), "tokenjuice-raw-"));
process.env.PI_CODING_AGENT_DIR = testAgentDir;
process.env.PI_TOKENJUICE_RAW_DIR = testRawDir;

function recordingHost() {
  const used = new Set();
  const registeredEvents = new Set();
  const handlers = new Map();
  const host = new Proxy(
    {},
    {
      get(_target, prop) {
        if (typeof prop !== "string") return undefined;
        used.add(prop);
        if (prop === "on") {
          return (name, handler) => {
            registeredEvents.add(name);
            handlers.set(name, handler);
          };
        }
        return () => {};
      },
      has() {
        return true;
      },
    },
  );
  return { host, used, registeredEvents, handlers };
}

function createContext() {
  const cwd = mkdtempSync(join(tmpdir(), "tokenjuice-cwd-"));
  return {
    cwd,
    source: "interactive",
    model: { provider: "openai-codex", id: "gpt-5.5" },
    hasUI: false,
    ui: { notify() {} },
    sessionManager: {
      getHeader: () => ({ cwd }),
      getCwd: () => cwd,
      getEntries: () => [],
      getBranch: () => [],
    },
  };
}

function largeEvent() {
  return {
    toolName: "exec_command",
    input: { cmd: "rg openclaw" },
    content: [{ type: "text", text: Array.from({ length: 700 }, (_, i) => `line-${i}: ${"x".repeat(90)}`).join("\n") }],
    details: {},
    isError: false,
  };
}

try {
  for (const enabled of ["1", "0"]) {
    process.env.PI_TOKENJUICE_ENABLED = enabled;
    const { host, used, registeredEvents, handlers } = recordingHost();
    wrappedRegister(host);

    // Registration touches no prompt/tool-shaping API…
    for (const api of FORBIDDEN_HOST_APIS) {
      assert.ok(!used.has(api), `enabled=${enabled}: register() must not touch host.${api}`);
    }
    // …and only ever subscribes to post-hoc result events.
    assert.ok(registeredEvents.has("tool_result"), `enabled=${enabled}: tool_result hook registered`);
    for (const event of registeredEvents) {
      assert.ok(
        !["before_agent_start", "session_start"].includes(event) || true,
        "informational: lifecycle hooks allowed as long as no forbidden API is used",
      );
    }

    // Firing compactions still touches nothing forbidden.
    const toolResult = handlers.get("tool_result");
    await toolResult(largeEvent(), createContext());
    await toolResult(largeEvent(), createContext());
    for (const api of FORBIDDEN_HOST_APIS) {
      assert.ok(!used.has(api), `enabled=${enabled}: tool_result firing must not touch host.${api}`);
    }
  }
  console.log("tokenjuice cache-stability smoke: all assertions passed");
} finally {
  if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
  else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
  if (previousEnabled === undefined) delete process.env.PI_TOKENJUICE_ENABLED;
  else process.env.PI_TOKENJUICE_ENABLED = previousEnabled;
  if (previousRawDir === undefined) delete process.env.PI_TOKENJUICE_RAW_DIR;
  else process.env.PI_TOKENJUICE_RAW_DIR = previousRawDir;
  rmSync(testAgentDir, { recursive: true, force: true });
  rmSync(testRawDir, { recursive: true, force: true });
}

