// Conservative canary policy around the generated tokenjuice bundle.
// Spec: oracle verdict 2026-06-09 (docs/pi-harness-optimisation/2026-06-08/
// findings/oracle-tokenjuice-dream-memory-verdict.md, Decision 1).
//
// The generated bundle stays pristine — `tokenjuice install pi` can regenerate
// it without touching this layer. Every house opinion lives in the wrapper:
//   - loading the extension (canary profile membership) is the opt-in;
//     PI_TOKENJUICE_ENABLED=0 / extensionConfig.tokenjuice.enabled=false kills
//   - per-class visible-char floors below which nothing compacts
//   - Agent results exempt entirely until canary evidence promotes them
//   - test/CI/compiler/git-evidence command output never compacts
//   - a compaction whose raw-recovery file is missing/unreadable is DROPPED:
//     the original result enters context untouched (requireRawRecovery)
//   - recovered raw files relocate from the bundle's /tmp dir into a durable
//     Pi-owned dir so debugging evidence survives reboots
//
// Cache safety: tool_result fires after the tool ran; nothing here can touch
// params.system or tools[] (proven in cache-stability.test.mjs).

import { copyFileSync, existsSync, mkdirSync, readFileSync, renameSync, unlinkSync } from "node:fs";
import { homedir } from "node:os";
import { basename, join, sep } from "node:path";

// Oracle "safer first-pass policy" thresholds (visible chars). The agent floor
// only applies when exemptAgents is explicitly turned off.
const DEFAULT_MIN_VISIBLE_CHARS = {
  bash: 8_000,
  bashOutput: 8_000,
  lsFind: 20_000,
  grepExec: 32_000,
  agent: 50_000,
};

const TOOL_CLASS = {
  bash: "bash",
  Bash: "bash",
  bash_output: "bashOutput",
  BashOutput: "bashOutput",
  ls: "lsFind",
  Ls: "lsFind",
  find: "lsFind",
  Find: "lsFind",
  grep: "grepExec",
  Grep: "grepExec",
  exec_command: "grepExec",
  write_stdin: "grepExec",
  agent: "agent",
  Agent: "agent",
  Task: "agent",
};

// Command shapes whose middles ARE the evidence (failing tests, compiler
// errors, diffs, service logs). Never compact these.
const EXEMPT_COMMAND_PATTERNS = [
  /\b(?:vitest|jest|mocha|pytest|cargo test|go test|pnpm test|npm test|yarn test|bun test)\b/,
  /\b(?:tsc|eslint|biome|ruff|mypy|clippy)\b/,
  /\bgit (?:diff|show|status|log)\b/,
  /\b(?:docker compose logs|kubectl logs|journalctl)\b/,
  /\b(?:CI|build|deploy|migration|db:migrate)\b/,
];

// L3: extensionConfig.tokenjuice from global + project settings (project wins).
// getExtensionConfig() hasn't landed on ExtensionAPI yet, so read directly —
// sanctioned interim pattern, see docs/config-layering.md.
let _settings;
function settingsConfig() {
  if (_settings !== undefined) return _settings;
  _settings = {};
  const files = [join(homedir(), ".pi", "agent", "settings.json"), join(process.cwd(), ".pi", "settings.json")];
  for (const file of files) {
    try {
      const cfg = JSON.parse(readFileSync(file, "utf8"))?.extensionConfig?.tokenjuice;
      if (cfg && typeof cfg === "object") _settings = { ..._settings, ...cfg };
    } catch {
      // missing or invalid settings file → defaults
    }
  }
  return _settings;
}

export function resetSettingsCache() {
  _settings = undefined;
}

function envBool(value) {
  if (value === undefined || value === "") return undefined;
  return !["0", "false", "no", "off"].includes(String(value).toLowerCase());
}

function envInt(value) {
  const n = Number.parseInt(value ?? "", 10);
  return Number.isFinite(n) && n > 0 ? n : undefined;
}

/** L1 defaults ← extensionConfig.tokenjuice (L3) ← PI_TOKENJUICE_* env (L4). */
export function resolveConfig(env = process.env) {
  const settings = settingsConfig();
  const globalMin = envInt(env.PI_TOKENJUICE_MIN_VISIBLE_CHARS);
  // tri-state: set env wins over settings in BOTH directions (L4 > L3)
  const compactAgentsEnv = envBool(env.PI_TOKENJUICE_COMPACT_AGENTS);
  return {
    enabled: envBool(env.PI_TOKENJUICE_ENABLED) ?? settings.enabled ?? true,
    requireRawRecovery: envBool(env.PI_TOKENJUICE_REQUIRE_RAW_RECOVERY) ?? settings.requireRawRecovery ?? true,
    rawDir: env.PI_TOKENJUICE_RAW_DIR ?? settings.rawDir ?? join(homedir(), ".pi", "agent", "tokenjuice"),
    exemptAgents: compactAgentsEnv !== undefined ? !compactAgentsEnv : (settings.exemptAgents ?? true),
    minVisibleChars: globalMin
      ? Object.fromEntries(Object.keys(DEFAULT_MIN_VISIBLE_CHARS).map((k) => [k, globalMin]))
      : { ...DEFAULT_MIN_VISIBLE_CHARS, ...(settings.minVisibleChars ?? {}) },
  };
}

function visibleText(event) {
  return (event?.content ?? [])
    .filter((item) => item?.type === "text")
    .map((item) => item.text ?? "")
    .join("\n");
}

function commandText(event) {
  const input = event?.input ?? {};
  if (typeof input.cmd === "string") return input.cmd;
  if (typeof input.command === "string") return input.command;
  return "";
}

export function isExemptCommand(command) {
  return EXEMPT_COMMAND_PATTERNS.some((pattern) => pattern.test(command));
}

/** Pre-filter: should the bundle's tool_result handler run at all? */
export function shouldDelegate(event, cfg) {
  const cls = TOOL_CLASS[event?.toolName];
  if (!cls) return true; // unknown tool → the bundle's own whitelist decides
  if (cls === "agent" && cfg.exemptAgents) return false;
  const text = visibleText(event);
  if (text.length < (cfg.minVisibleChars[cls] ?? DEFAULT_MIN_VISIBLE_CHARS[cls])) return false;
  if ((cls === "bash" || cls === "grepExec") && isExemptCommand(commandText(event))) return false;
  // Structured idempotency guard only — no text sniffing (output merely
  // mentioning compaction must not bypass it; the bundle additionally guards
  // against literal re-compaction of its own notices internally).
  if (event?.details?.tokenjuice?.compacted === true) return false;
  return true;
}

/**
 * Post-filter: a compacted result must carry a readable raw-recovery file or
 * the compaction is dropped (returns undefined → host keeps the original
 * result). Readable raw files outside rawDir relocate into it, with every
 * path mention (details + notice text) rewritten.
 */
export function enforceRawRecovery(result, cfg) {
  const tj = result?.details?.tokenjuice;
  if (tj?.compacted !== true) return result;
  const rawPath = typeof tj.rawPath === "string" ? tj.rawPath : undefined;
  if (!rawPath || !existsSync(rawPath)) return cfg.requireRawRecovery ? undefined : result;
  if (rawPath === cfg.rawDir || rawPath.startsWith(cfg.rawDir + sep)) return result;

  const dest = join(cfg.rawDir, basename(rawPath));
  try {
    mkdirSync(cfg.rawDir, { recursive: true });
    try {
      renameSync(rawPath, dest);
    } catch {
      copyFileSync(rawPath, dest);
      try {
        unlinkSync(rawPath);
      } catch {
        // best effort: the /tmp original lingering is harmless
      }
    }
  } catch {
    return result; // relocation failed → raw stays readable at the original path
  }

  const rewrite = (text) => (typeof text === "string" ? text.split(rawPath).join(dest) : text);
  result.details.tokenjuice = { ...tj, rawPath: dest, recoveryHint: rewrite(tj.recoveryHint) };
  for (const item of result.content ?? []) {
    if (item?.type === "text") item.text = rewrite(item.text);
  }
  return result;
}

export function wrapToolResult(inner) {
  return async (event, ctx) => {
    const cfg = resolveConfig();
    if (!cfg.enabled) return undefined;
    if (!shouldDelegate(event, cfg)) return undefined;
    return enforceRawRecovery(await inner(event, ctx), cfg);
  };
}

/**
 * Wrap a tokenjuice register function so its tool_result hook obeys policy.
 *
 * Delegation contract: the shim prototype-chains to the host API and shadows
 * only `on`. This relies on (a) the host's methods being closure-based (the
 * loader builds ExtensionAPI as an object literal that never reads `this`)
 * and (b) the bundle consuming `pi` purely by method call (no spread /
 * destructure / own-key enumeration). If either changes, switch to an
 * explicit forwarding object.
 */
export function withPolicy(register) {
  return (pi) => {
    const shim = Object.create(pi);
    shim.on = (name, handler) => pi.on(name, name === "tool_result" ? wrapToolResult(handler) : handler);
    return register(shim);
  };
}

